package com.archon.address;

import com.archon.model.BodyPart;
import com.archon.model.EquipmentSlot;
import com.archon.model.Vec2;

import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public final class AddressSyntax {
    private static final Pattern COORDINATES =
            Pattern.compile("([+-]?\\d+)\\s*,\\s*([+-]?\\d+)");
    private static final Pattern RELATIVE =
            Pattern.compile("(ne|nw|se|sw|n|s|e|w)(\\d+)?", Pattern.CASE_INSENSITIVE);

    private AddressSyntax() {}

    sealed interface Path {}
    record RootPath() implements Path {}
    record ContentsPath() implements Path {}
    record BodyPath(BodyPart part) implements Path {}
    record PackPath(String query) implements Path {}
    record SlotPath(EquipmentSlot slot) implements Path {}
    record BadPath(String reason) implements Path {}

    sealed interface Tile {}
    record AbsoluteTile(int x, int y) implements Tile {}
    record RelativeTile(Vec2 direction, int distance) implements Tile {}
    record AnchorTile(String id) implements Tile {}
    record BadTile(String reason) implements Tile {}

    public static Optional problem(String raw) {
        String reason = switch (Address.parse(raw)) {
            case Address.Invalid invalid -> invalid.reason();
            case Address.EntityAddr entity -> pathProblem(path(entity.path(), true));
            case Address.InventoryAddr inventory -> pathProblem(path(inventory.path(), false));
            case Address.TileAddr address ->
                    tile(address.spec()) instanceof BadTile bad ? bad.reason() : null;
        };
        return Optional.ofNullable(reason);
    }

    static Path path(String text, boolean entityPath) {
        if (entityPath && text.isEmpty()) {
            return new RootPath();
        }
        if (entityPath && text.equals("contents")) {
            return new ContentsPath();
        }
        if (entityPath && text.startsWith("body/")) {
            BodyPart part = BodyPart.parse(text.substring("body/".length()));
            return part == null ? badPath(text) : new BodyPath(part);
        }
        if (text.equals("pack")) {
            return new PackPath(null);
        }
        if (text.startsWith("pack/")) {
            String query = text.substring("pack/".length());
            return query.isBlank() ? badPath(text) : new PackPath(query);
        }

        return EquipmentSlot.parse(text)
                .map(SlotPath::new)
                .orElseGet(() -> badPath(text));
    }

    static Tile tile(String spec) {
        try {
            if (spec.contains(",")) {
                Matcher coordinates = COORDINATES.matcher(spec.trim());
                if (!coordinates.matches()) {
                    return new BadTile("invalid coordinates \"" + spec + "\"; use @x,y");
                }
                return new AbsoluteTile(
                        Integer.parseInt(coordinates.group(1)),
                        Integer.parseInt(coordinates.group(2))
                );
            }

            Matcher relative = RELATIVE.matcher(spec);
            if (relative.matches()) {
                return new RelativeTile(
                        Vec2.dir(relative.group(1)),
                        relative.group(2) == null ? 1 : Integer.parseInt(relative.group(2))
                );
            }
        } catch (NumberFormatException exception) {
            return new BadTile("tile coordinate or distance is too large in \"" + spec + "\"");
        }
        return new AnchorTile(spec);
    }

    private static BadPath badPath(String text) {
        return new BadPath("unknown target path \"" + text + "\"");
    }

    private static String pathProblem(Path path) {
        return path instanceof BadPath bad ? bad.reason() : null;
    }
}



package com.archon.exec;

import com.archon.verb.ExitCode;

import java.util.List;
import java.util.Optional;

public record ExecutionTrace(List stages) {
    public enum State {
        EXECUTED, SKIPPED, NOT_REACHED, INTERRUPTED_BEFORE, INTERRUPTED_DURING
    }

    public record Stage(int index, State state, ExitCode code, int allocation, int charged, boolean paidExecuted,
                        boolean terminalExecuted, String reason) {
        public boolean interrupted() {
            return state == State.INTERRUPTED_BEFORE || state == State.INTERRUPTED_DURING;
        }
    }

    public ExecutionTrace {
        stages = List.copyOf(stages);
    }

    public ExitCode lastCode() {
        for (int i = stages.size() - 1; i >= 0; i--) {
            if (stages.get(i).code() != null) {
                return stages.get(i).code();
            }
        }
        return ExitCode.SUCCESS;
    }

    public int charged() {
        return stages.stream().mapToInt(Stage::charged).reduce(0, Math::addExact);
    }

    public boolean paidExecuted() {
        return stages.stream().anyMatch(Stage::paidExecuted);
    }

    public boolean terminalExecuted() {
        return stages.stream().anyMatch(Stage::terminalExecuted);
    }

    public Optional interruption() {
        return stages.stream().filter(Stage::interrupted).findFirst();
    }
}



package com.archon.exec;

import com.archon.command.Ast;
import com.archon.event.EventBus;
import com.archon.model.World;
import com.archon.verb.*;

import java.util.Objects;

public final class InvocationRunner {
    public record Result(ExitCode code, Material output, boolean paid, boolean terminal) {}

    private final World world;
    private final EventBus bus;
    private final VerbCatalog catalog;

    public InvocationRunner(World world, EventBus bus, VerbCatalog catalog) {
        this.world = Objects.requireNonNull(world, "world");
        this.bus = Objects.requireNonNull(bus, "bus");
        this.catalog = Objects.requireNonNull(catalog, "catalog");
    }

    public Result run(Ast.Invocation invocation, Material input, boolean piped) {
        VerbDefinition definition = Objects.requireNonNull(catalog.get(invocation.verb()), "unknown invocation");
        if (piped && input == null) {
            bus.narrate("no material was produced for " + invocation.verb());
            return new Result(ExitCode.BLOCKED, null, false, false);
        }
        if (input != null && !definition.input().contains(kind(input))) {
            throw new IllegalStateException("unexpected input kind for " + invocation.verb());
        }

        VerbContext context = new VerbContext(world, invocation, bus, input);
        ExitCode code = Objects.requireNonNull(definition.action().execute(context), "verb returned no outcome");
        if (code == ExitCode.INVALID) {
            throw new IllegalStateException(invocation.verb() + " returned INVALID after submission validation");
        }
        if (context.materialOut != null && !definition.output().contains(kind(context.materialOut))) {
            throw new IllegalStateException("undeclared output kind from " + invocation.verb());
        }

        return new Result(code, context.materialOut, !definition.free(),
                definition.terminal() && code == ExitCode.SUCCESS);
    }

    private static MaterialKind kind(Material material) {
        return switch (material) {
            case Material.OfItem item -> {
                Objects.requireNonNull(item.item(), "material item");
                yield MaterialKind.ITEM;
            }
            case Material.OfSubstance substance -> {
                Objects.requireNonNull(substance.substance(), "material substance");
                yield MaterialKind.SUBSTANCE;
            }
        };
    }
}



package com.archon.exec;

import com.archon.command.Ast;
import com.archon.verb.Check;

import java.util.Objects;

public final class SubmissionChecks {
    public record Review(Check check, SubmissionQuote quote) {}

    private final Validator validator;
    private final ExecutionPolicy policy;
    private final RoundState round;

    public SubmissionChecks(Validator validator, ExecutionPolicy policy, RoundState round) {
        this.validator = Objects.requireNonNull(validator, "validator");
        this.policy = Objects.requireNonNull(policy, "policy");
        this.round = Objects.requireNonNull(round, "round");
    }

    public Review review(Ast.Line line) {
        Check check = validator.validate(line);
        if (!check.valid()) {
            return new Review(check, null);
        }

        SubmissionQuote quote;
        try {
            quote = policy.quote(line, round);
        } catch (ArithmeticException exception) {
            return new Review(Check.invalid("submitted allocation exceeds the supported AP range", "submit less work"),
                    null);
        }

        if (!quote.affordable()) {
            return new Review(Check.blocked(
                    String.format("insufficient AP: %d AP tax + %d AP allocation = %d. Available: %d.", quote.tax(),
                            quote.allocation(), quote.requiredAp(), quote.availableAp()),
                    "reduce the submitted allocation"), quote);
        }
        return new Review(Check.ok(), quote);
    }
}



package com.archon.exec;

public final class SubmissionQuote {
    private final boolean free;
    private final int allocation;
    private final int tax;
    private final int availableAp;
    private final EconomyRules rules;

    SubmissionQuote(boolean free, int allocation, RoundState round) {
        java.util.Objects.requireNonNull(round, "round");
        if (allocation < 0 || (free && allocation != 0)) {
            throw new IllegalArgumentException(
                    "allocation must be nonnegative and zero for free-only submissions");
        }

        this.free = free;
        this.allocation = allocation;
        this.rules = round.rules();
        this.tax = free ? 0 : rules.taxForNextLine(round.linesUsed());
        this.availableAp = round.ap();
    }

    public boolean free() {
        return free;
    }

    public int allocation() {
        return allocation;
    }

    public int tax() {
        return tax;
    }

    public int availableAp() {
        return availableAp;
    }

    public long requiredAp() {
        return (long) allocation + tax;
    }

    public boolean affordable() {
        return requiredAp() <= availableAp;
    }

    /**
     * Allocation forfeiture after commitment tax, excluding the tax itself.
     * An unaffordable submission cannot commit and has no settlement quote.
     */
    public int forfeiture() {
        if (!affordable()) {
            throw new IllegalStateException(
                    "an unaffordable submission cannot incur forfeiture");
        }
        return free ? 0 : rules.breakCharge(allocation, availableAp - tax);
    }
}



package com.archon.system.combat;

import java.util.Objects;

/** Facts captured when one readied reaction fires; damage retains its authored meaning. */
public record Reaction(String sourceId, String sourceName, String description, int damage) {

    public Reaction {
        Objects.requireNonNull(sourceId, "sourceId");
        Objects.requireNonNull(sourceName, "sourceName");
        Objects.requireNonNull(description, "description");
        if (sourceId.isBlank() || sourceName.isBlank() || description.isBlank()) {
            throw new IllegalArgumentException("reaction reporting fields must not be blank");
        }
        if (damage < 0) {
            throw new IllegalArgumentException("reaction damage must be nonnegative");
        }
    }
}



package com.archon.system.environment;

import com.archon.model.Actor;
import com.archon.model.Entity;
import com.archon.model.EquipmentSlot;
import com.archon.model.GameMap;
import com.archon.model.Item;
import com.archon.model.Tag;
import com.archon.model.Vec2;
import com.archon.model.World;
import com.archon.system.spatial.SpatialService;

import java.util.Objects;

/** Eligibility and effects of direct ignition, separate from periodic fire spread. */
public final class Ignition {

    private Ignition() {}

    public static boolean hasFlame(Actor actor) {
        Objects.requireNonNull(actor, "actor");
        Item left = actor.inventory().equipped(EquipmentSlot.HAND_LEFT);
        Item right = actor.inventory().equipped(EquipmentSlot.HAND_RIGHT);
        return (left != null && left.has(Tag.LIT)) || (right != null && right.has(Tag.LIT));
    }

    public static boolean entity(Entity entity) {
        Objects.requireNonNull(entity, "entity");
        if (!entity.has(Tag.FLAMMABLE)) {
            return false;
        }
        entity.ignite();
        return true;
    }

    public static boolean tile(World world, Vec2 at) {
        Objects.requireNonNull(world, "world");
        Objects.requireNonNull(at, "position");

        GameMap.Tile tile = world.map().tile(at);
        if (tile == null) {
            throw new IllegalArgumentException("Position is outside the map: " + at);
        }
        if (!tile.has(Tag.OIL) && !tile.has(Tag.FLAMMABLE)) {
            return false;
        }

        world.map().addTag(at, Tag.BURNING);
        Entity occupant = SpatialService.entityAt(world, at);
        if (occupant != null) {
            entity(occupant);
        }
        return true;
    }
}



package com.archon.system.environment;

import com.archon.address.Address;
import com.archon.address.Resolved;
import com.archon.model.Actor;
import com.archon.model.Entity;
import com.archon.model.GameMap;
import com.archon.model.Item;
import com.archon.model.Prop;
import com.archon.model.Tag;
import com.archon.model.Vec2;
import com.archon.model.World;
import com.archon.system.item.ItemMoves;
import com.archon.system.spatial.SpatialService;

import java.util.Objects;

/** Immediate finite extraction, container consumption, and substance application. */
public final class Substances {

    public sealed interface Extraction permits Portion, Unavailable {}

    public record Portion(Tag substance) implements Extraction {
        public Portion {
            Objects.requireNonNull(substance, "substance");
        }
    }

    public enum Unavailable implements Extraction {
        EMPTY, STALE_SOURCE
    }

    private Substances() {}

    /**
     * Extracts the existing portion from an authoritative target.
     * Entity sources use an actor's main hand or a prop's contents.
     */
    public static Extraction extract(World world, Resolved.Target source) {
        Objects.requireNonNull(world, "world");
        Objects.requireNonNull(source, "source");

        if (source instanceof Resolved.OnItem selected && ItemMoves.checkSource(world.map(), selected.item(),
                selected.location()) != ItemMoves.Result.SUCCESS) {
            return Unavailable.STALE_SOURCE;
        }

        Item item = sourceItem(source);
        if (item != null) {
            Tag substance = item.consumeSubstance();
            return substance == null ? Unavailable.EMPTY : new Portion(substance);
        }

        if (source instanceof Resolved.OnTile target && target.layer() != Address.Layer.CEILING) {
            GameMap.Tile tile = requireDestination(world, target.pos());
            Tag substance = tile.has(Tag.OIL) ? Tag.OIL : tile.has(Tag.WATER) ? Tag.WATER : null;
            if (substance == null) {
                return Unavailable.EMPTY;
            }
            if (!world.map().removeTag(target.pos(), substance)) {
                throw new IllegalStateException("selected substance disappeared during extraction");
            }
            return new Portion(substance);
        }

        return Unavailable.EMPTY;
    }

    /** Keeps the container and returns the consumed substance, or null when empty. */
    public static Tag pour(World world, Vec2 at, Item container) {
        Objects.requireNonNull(container, "container");
        requireDestination(world, at);

        Tag substance = container.consumeSubstance();
        if (substance != null) {
            apply(world, at, substance);
        }
        return substance;
    }

    public static void spill(World world, Vec2 at, Tag substance) {
        Objects.requireNonNull(substance, "substance");
        requireDestination(world, at);
        apply(world, at, substance);
    }

    /** Invalid coordinates are programmer errors and must be detected before consumption. */
    public static GameMap.Tile requireDestination(World world, Vec2 at) {
        Objects.requireNonNull(world, "world");
        Objects.requireNonNull(at, "position");

        GameMap.Tile tile = world.map().tile(at);
        if (tile == null) {
            throw new IllegalArgumentException("Position is outside the map: " + at);
        }
        return tile;
    }

    private static Item sourceItem(Resolved.Target source) {
        if (source instanceof Resolved.OnItem target) {
            return target.item();
        }
        if (source instanceof Resolved.OnEntity target) {
            if (target.entity() instanceof Actor actor) {
                return actor.mainHand();
            }
            if (target.entity() instanceof Prop prop) {
                return prop.contents();
            }
        }
        return null;
    }

    private static void apply(World world, Vec2 at, Tag substance) {
        GameMap map = world.map();
        map.addTag(at, Tag.LIQUID);
        map.addTag(at, substance);

        if (substance == Tag.OIL) {
            map.addTag(at, Tag.FLAMMABLE);
        }
        if (substance == Tag.WATER) {
            map.addTag(at, Tag.CONDUCTIVE);
        }

        Entity occupant = SpatialService.entityAt(world, at);
        if (occupant != null && substance == Tag.OIL) {
            occupant.applyTag(Tag.FLAMMABLE);
        }
    }
}



package com.archon.system.item;

import com.archon.model.Actor;
import com.archon.model.EquipmentSlot;
import com.archon.model.GameMap;
import com.archon.model.Inventory;
import com.archon.model.Item;
import com.archon.model.ItemLocation;
import com.archon.model.Vec2;

import java.util.Objects;

/**
 * Synchronous item operations over existing ownership boundaries.
 *
 * Expected rejection does not mutate either owner. Successful relocation assumes
 * valid initial ownership and leaves the item at its intended destination.
 * Unexpected mutation failures are programming defects, not rollback requests.
 */
public final class ItemMoves {

    public enum Result {
        SUCCESS(null),
        STALE_SOURCE("item no longer at its source"),
        PACK_FULL("pack full (" + Inventory.PACK_MAX + ")"),
        ALREADY_AT_DESTINATION("item is already at the destination"),
        NOT_PACKED("item is not in a pack"),
        SLOT_OCCUPIED("equipment slot is occupied");

        private final String reason;

        Result(String reason) {
            this.reason = reason;
        }

        public String reason() {
            return reason;
        }

        /** For callers whose established invariants require relocation to succeed. */
        public void requireSuccess() {
            if (this != SUCCESS) {
                throw new IllegalStateException(reason);
            }
        }
    }

    private ItemMoves() {}

    /** Finds the current carried location by identity, or null when not carried. */
    public static ItemLocation carriedLocation(Actor owner, Item item) {
        Objects.requireNonNull(owner, "owner");
        Objects.requireNonNull(item, "item");

        Inventory inventory = owner.inventory();
        if (packed(inventory, item)) {
            return new ItemLocation.Pack(owner);
        }
        for (EquipmentSlot slot : EquipmentSlot.values()) {
            if (inventory.equipped(slot) == item) {
                return new ItemLocation.Equipment(owner, slot);
            }
        }
        return null;
    }

    public static Result checkSource(GameMap map, Item item, ItemLocation source) {
        Objects.requireNonNull(map, "map");
        Objects.requireNonNull(item, "item");
        Objects.requireNonNull(source, "source");

        boolean present = switch (source) {
            case ItemLocation.Pack pack -> packed(pack.owner().inventory(), item);
            case ItemLocation.Equipment equipment ->
                    equipment.owner().inventory().equipped(equipment.slot()) == item;
            case ItemLocation.Contents contents -> contents.owner().contents() == item;
            case ItemLocation.Ground ground -> requireTile(map, ground.pos()).ground().contains(item);
        };
        return present ? Result.SUCCESS : Result.STALE_SOURCE;
    }

    /** Checks relocation into a pack, without reserving either source or destination. */
    public static Result checkToPack(GameMap map, Item item, ItemLocation source, Actor recipient) {
        Objects.requireNonNull(recipient, "recipient");

        Result selected = checkSource(map, item, source);
        if (selected != Result.SUCCESS) {
            return selected;
        }
        if (recipient.inventory().isPackFull()) {
            return Result.PACK_FULL;
        }
        if (carriedLocation(recipient, item) != null) {
            return Result.ALREADY_AT_DESTINATION;
        }
        return Result.SUCCESS;
    }

    /** Moves an external item into a pack; already-carried selections do not relocate. */
    public static Result toPack(GameMap map, Item item, ItemLocation source, Actor recipient) {
        Result checked = checkToPack(map, item, source, recipient);
        if (checked != Result.SUCCESS) {
            return checked;
        }

        requireMutation(detach(map, item, source));
        requireMutation(recipient.inventory().addToPack(item));
        return Result.SUCCESS;
    }

    /** Drops a carried item at its owner's current position. */
    public static Result drop(GameMap map, Item item, ItemLocation source) {
        Objects.requireNonNull(source, "source");
        if (!(source instanceof ItemLocation.Pack || source instanceof ItemLocation.Equipment)) {
            throw new IllegalArgumentException("drop requires a carried source");
        }

        Result selected = checkSource(map, item, source);
        if (selected != Result.SUCCESS) {
            return selected;
        }
        Vec2 destination = source.pos();
        if (requireTile(map, destination).ground().contains(item)) {
            return Result.ALREADY_AT_DESTINATION;
        }

        requireMutation(detach(map, item, source));
        map.placeGroundItem(destination, item);
        return Result.SUCCESS;
    }

    /** Equips a selected packed item without displacing an occupied slot. */
    public static Result equip(Item item, ItemLocation source, EquipmentSlot slot) {
        Objects.requireNonNull(item, "item");
        Objects.requireNonNull(source, "source");
        Objects.requireNonNull(slot, "slot");

        if (!(source instanceof ItemLocation.Pack pack)) {
            return Result.NOT_PACKED;
        }

        Inventory inventory = pack.owner().inventory();
        if (!packed(inventory, item)) {
            return Result.STALE_SOURCE;
        }
        if (inventory.equipped(slot) != null) {
            return Result.SLOT_OCCUPIED;
        }

        requireMutation(inventory.equipFromPack(item, slot));
        return Result.SUCCESS;
    }

    /** Removes exactly the selected source item, without inventing a destination. */
    public static Result remove(GameMap map, Item item, ItemLocation source) {
        Result selected = checkSource(map, item, source);
        if (selected != Result.SUCCESS) {
            return selected;
        }

        requireMutation(detach(map, item, source));
        return Result.SUCCESS;
    }

    private static boolean packed(Inventory inventory, Item item) {
        return inventory.pack().stream().anyMatch(candidate -> candidate == item);
    }

    private static boolean detach(GameMap map, Item item, ItemLocation source) {
        return switch (source) {
            case ItemLocation.Pack pack -> pack.owner().inventory().remove(item);
            case ItemLocation.Equipment equipment ->
                    equipment.owner().inventory().removeEquipped(equipment.slot()) == item;
            case ItemLocation.Contents contents -> contents.owner().removeContents() == item;
            case ItemLocation.Ground ground -> map.removeGroundItem(ground.pos(), item);
        };
    }

    private static GameMap.Tile requireTile(GameMap map, Vec2 position) {
        Objects.requireNonNull(position, "position");
        GameMap.Tile tile = map.tile(position);
        if (tile == null) {
            throw new IllegalArgumentException("Position is outside the map: " + position);
        }
        return tile;
    }

    private static void requireMutation(boolean completed) {
        if (!completed) {
            throw new IllegalStateException("item mutation failed after its preconditions were established");
        }
    }
}



package com.archon.verb;

import com.archon.address.Address;
import com.archon.address.Resolved;
import com.archon.model.Vec2;
import com.archon.system.environment.Substances;

sealed interface DeliveryTarget {

    enum Mode {
        POUR,
        THROW
    }

    record Selected(Vec2 pos) implements DeliveryTarget {}

    record Rejected(Check check) implements DeliveryTarget {}

    static DeliveryTarget select(VerbContext c, Mode mode) {
        Resolved resolved = VerbHelpers.resolve(c, c.inv.arg(c.pipedInput ? 0 : 1));
        Check resolution = VerbTargets.resolution(resolved);
        if (!resolution.valid()) {
            return new Rejected(resolution);
        }

        boolean accepted = resolved instanceof Resolved.OnEntity
                || resolved instanceof Resolved.OnTile tile && tile.layer() != Address.Layer.CEILING
                || mode == Mode.THROW && resolved instanceof Resolved.OnBody;
        if (!accepted) {
            String reason = mode == Mode.POUR
                    ? "pour needs an entity or floor tile"
                    : "throw needs an entity or floor target";
            return new Rejected(Check.blocked(reason, null));
        }

        Resolved.Target target = (Resolved.Target) resolved;
        if (mode == Mode.POUR) {
            Check reach = VerbTargets.reachable(c, target);
            if (!reach.valid()) {
                return new Rejected(reach);
            }
        }

        Substances.requireDestination(c.world, target.pos());
        return new Selected(target.pos());
    }
}



package com.archon.verb;

import com.archon.address.Address;
import com.archon.address.Resolved;
import com.archon.model.*;

import java.util.Optional;

final class TargetDescriptions {
    private TargetDescriptions() {}

    static String inspect(World world, Resolved.Target target) {
        return switch (target) {
            case Resolved.OnEntity entity -> entity(entity.entity(), null);
            case Resolved.OnBody body -> entity(body.actor(), body.part());
            case Resolved.OnItem selected -> item(selected.item());
            case Resolved.OnLocation location ->
                    location.location() instanceof ItemLocation.Pack pack ? pack.owner().id() + "/pack — " + pack.owner().inventory().pack() : "nothing there";
            case Resolved.OnTile tile -> tile(world, tile);
        };
    }

    static Optional list(World world, Resolved.Target target) {
        String listing = switch (target) {
            case Resolved.OnLocation location when location.location() instanceof ItemLocation.Pack pack ->
                    pack.owner().inventory().isPackEmpty() ? "(empty)" : String.join("\n",
                            pack.owner().inventory().pack().stream().map(
                                    item -> "  " + item.id() + "  " + item.tags()).toList());
            case Resolved.OnLocation ignored -> "(empty)";
            case Resolved.OnItem item -> "  " + item.item().id() + "  " + item.item().tags();
            case Resolved.OnTile tile -> tile.layer() == Address.Layer.CEILING ? "ceiling — tags " + world.tile(
                    tile.pos()).ceiling() : world.tile(tile.pos()).ground().toString();
            default -> null;
        };
        return Optional.ofNullable(listing);
    }

    private static String entity(Entity entity, BodyPart focus) {
        StringBuilder output = new StringBuilder(
                entity.name() + " \"" + entity.id() + "\" — HP " + entity.hp() + "/" + entity.maxHp() + ", Armor " + entity.armor());
        output.append("\n  Tags: ").append(entity.tags());

        if (entity instanceof Actor actor) {
            if (actor.mainHand() != null) {
                output.append("\n  Holding: ").append(actor.mainHand().name());
            }
            if (actor.readied() != null && !actor.isReadiedSpent()) {
                output.append("\n  READIED: ").append(actor.readied().description()).append(" (").append(
                        actor.readied().damage()).append(" dmg)");
            }
            for (BodyPart part : BodyPart.values()) {
                if (focus != null && focus != part) continue;
                output.append(String.format("%n  %-6s %3d%%  x%.1f%s", part.path,
                        Math.max(5, 70 + part.hitMod - entity.evasion()), part.damageMult,
                        Boolean.TRUE.equals(actor.crippled().get(part)) ? " CRIPPLED" : ""));
            }
        }
        return output.toString();
    }

    private static String item(Item item) {
        return item.name() + " — tags " + item.tags() + (item.substance() == null ? "" : ", contains " + item.substance());
    }

    private static String tile(World world, Resolved.OnTile target) {
        GameMap.Tile tile = world.tile(target.pos());
        return target.layer() == Address.Layer.CEILING ? target.pos() + " ceiling — tags " + tile.ceiling() : target.pos() + " " + (tile.isWall() ? "WALL" : "floor") + " — tags " + tile.tags() + (tile.ground().isEmpty() ? "" : ", ground " + tile.ground());
    }
}



package com.archon.verb;

import com.archon.address.AddressSyntax;
import com.archon.model.BodyPart;

final class VerbSyntax {
    private VerbSyntax() {}

    static Check address(ValidationContext c, int index) {
        String raw = c.inv.arg(index);
        if (raw == null) {
            return Check.invalid(c.inv.verb() + " needs an address", null);
        }
        return address(raw);
    }

    static Check optionalAddress(ValidationContext c, int index) {
        return c.inv.arg(index) == null ? Check.ok() : address(c, index);
    }

    static Check item(ValidationContext c, int index) {
        if (c.pipedInput) {
            return Check.ok();
        }
        String raw = c.inv.arg(index);
        return raw == null || raw.isBlank()
                ? Check.invalid("an item is required", null)
                : address(itemAddress(raw));
    }

    static Check delivery(ValidationContext c) {
        Check target = address(c, c.pipedInput ? 0 : 1);
        return target.valid() ? item(c, 0) : target;
    }

    static Check aimedAddress(ValidationContext c, boolean optional) {
        String aim = c.inv.flag("aim");
        if (aim != null && BodyPart.parse(aim) == null) {
            return Check.invalid("unknown hit location \"" + aim + "\"",
                    "valid: head, torso, arm.l, arm.r, legs");
        }
        return optional ? optionalAddress(c, 0) : address(c, 0);
    }

    static String itemAddress(String raw) {
        return raw.startsWith("@") || raw.contains("/") ? raw : "/pack/" + raw;
    }

    private static Check address(String raw) {
        return AddressSyntax.problem(raw)
                .map(reason -> Check.invalid(reason, null))
                .orElseGet(Check::ok);
    }
}



package com.archon.address;

import com.archon.model.*;

final class PathResolver {
    private PathResolver() {}

    static Resolved entity(Address.EntityAddr address, World world) {
        AddressSyntax.Path path = AddressSyntax.path(address.path(), true);
        if (path instanceof AddressSyntax.BadPath bad) {
            return new Resolved.Failure(Resolved.Problem.BAD_SYNTAX, bad.reason());
        }

        Entity entity = world.get(address.id());
        if (entity == null) {
            return new Resolved.Failure(Resolved.Problem.UNKNOWN_ENTITY, "unknown entity \"" + address.id() + "\"");
        }
        if (!entity.alive()) {
            return new Resolved.Failure(Resolved.Problem.DEAD_ENTITY, entity.id() + " is no longer alive");
        }

        return switch (path) {
            case AddressSyntax.RootPath ignored -> new Resolved.OnEntity(entity);
            case AddressSyntax.ContentsPath ignored -> entity instanceof Prop prop ? selection(prop.contents(),
                    new ItemLocation.Contents(prop)) : unsupported();
            case AddressSyntax.BodyPath body ->
                    entity instanceof Actor actor ? new Resolved.OnBody(actor, body.part()) : unsupported();
            default -> entity instanceof Actor actor ? inventory(actor, path) : unsupported();
        };
    }

    static Resolved inventory(Actor actor, String path) {
        return inventory(actor, AddressSyntax.path(path, false));
    }

    private static Resolved inventory(Actor actor, AddressSyntax.Path path) {
        return switch (path) {
            case AddressSyntax.PackPath pack -> pack.query() == null ? new Resolved.OnLocation(
                    new ItemLocation.Pack(actor)) : actor.inventory().find(pack.query()).map(
                    item -> new Resolved.OnItem(item, new ItemLocation.Pack(actor))).orElseGet(
                    () -> new Resolved.Failure(Resolved.Problem.ITEM_NOT_FOUND,
                            "no packed item \"" + pack.query() + "\" on " + actor.id()));
            case AddressSyntax.SlotPath slot ->
                    selection(actor.inventory().equipped(slot.slot()), new ItemLocation.Equipment(actor, slot.slot()));
            case AddressSyntax.BadPath bad -> new Resolved.Failure(Resolved.Problem.BAD_SYNTAX, bad.reason());
            default -> unsupported();
        };
    }

    private static Resolved selection(Item item, ItemLocation location) {
        return item == null ? new Resolved.OnLocation(location) : new Resolved.OnItem(item, location);
    }

    private static Resolved unsupported() {
        return new Resolved.Failure(Resolved.Problem.UNSUPPORTED_PATH, "target does not support that path");
    }
}



package com.archon.address;

import com.archon.model.Entity;
import com.archon.model.Vec2;
import com.archon.model.World;

final class TileResolver {
    private TileResolver() {}

    static Resolved resolve(Address.TileAddr address, World world) {
        return switch (AddressSyntax.tile(address.spec())) {
            case AddressSyntax.BadTile bad -> new Resolved.Failure(Resolved.Problem.INVALID_TILE, bad.reason());
            case AddressSyntax.AbsoluteTile absolute -> bounded(absolute.x(), absolute.y(), address.layer(), world);
            case AddressSyntax.RelativeTile relative ->
                    bounded(world.thrall().pos().x() + (long) relative.direction().x() * relative.distance(),
                            world.thrall().pos().y() + (long) relative.direction().y() * relative.distance(),
                            address.layer(), world);
            case AddressSyntax.AnchorTile anchor -> anchored(anchor.id(), address.layer(), world);
        };
    }

    private static Resolved anchored(String id, Address.Layer layer, World world) {
        Entity anchor = id.equalsIgnoreCase("self") ? world.thrall() : world.get(id);
        if (anchor == null) {
            return new Resolved.Failure(Resolved.Problem.UNKNOWN_ENTITY,
                    "unknown tile reference \"" + id + "\"; use @x,y, @self, @e2, or @entityId");
        }
        if (!anchor.alive()) {
            return new Resolved.Failure(Resolved.Problem.DEAD_ENTITY, anchor.id() + " is no longer alive");
        }
        return bounded(anchor.pos().x(), anchor.pos().y(), layer, world);
    }

    private static Resolved bounded(long x, long y, Address.Layer layer, World world) {
        if (x < 0 || y < 0 || x >= world.width() || y >= world.height()) {
            return new Resolved.Failure(Resolved.Problem.OUT_OF_BOUNDS,
                    "tile (" + x + "," + y + ") is outside the map");
        }
        return new Resolved.OnTile(new Vec2((int) x, (int) y), layer);
    }
}



