package com.archon.app;

import com.archon.command.CommandParser;
import com.archon.command.InvocationParser;
import com.archon.event.EventBus;
import com.archon.exec.*;
import com.archon.model.World;
import com.archon.system.combat.ReactionSystem;
import com.archon.system.environment.SimulationSystem;
import com.archon.verb.CommandManual;
import com.archon.verb.VerbCatalog;

public final class ExecutionSetup {

    private ExecutionSetup() {}

    public static Executor create(World world, EventBus bus, RoundState round) {
        CommandManual manual = new CommandManual(round.rules());
        VerbCatalog catalog = DefaultVerbs.create(manual);
        manual.bind(catalog);
        ExecutionPolicy policy = new ExecutionPolicy(catalog);
        CommandParser parser = new CommandParser(new InvocationParser(catalog));
        SubmissionChecks submissions = new SubmissionChecks(new Validator(world, catalog), policy, round);
        Auditor auditor = new Auditor(world, bus, round, submissions);
        PipelineRunner pipelines = new PipelineRunner(new InvocationRunner(world, bus, catalog));
        Interrupts interrupts = new Interrupts(() -> ReactionSystem.fire(world), bus);
        StageRunner stages = new StageRunner(bus, pipelines, policy, interrupts);
        SettlementManager settlement = new SettlementManager(world, bus, round, interrupts);

        return new Executor(world, bus, round, parser, submissions, auditor, stages, settlement,
                () -> SimulationSystem.tick(world));
    }
}



package com.archon.command;

import com.archon.verb.VerbCatalog;
import com.archon.verb.VerbDefinition;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.regex.Pattern;

/** Parses a single command's arguments and metadata-declared options. */
public final class InvocationParser {

    private static final Pattern NUMERIC = Pattern.compile("-?\\d+");

    private final VerbCatalog catalog;

    public InvocationParser(VerbCatalog catalog) {
        this.catalog = Objects.requireNonNull(catalog, "catalog");
    }

    Ast.Invocation parse(List tokens) {
        String name = tokens.getFirst().toLowerCase(Locale.ROOT);
        VerbDefinition definition = catalog.get(name);
        if (definition == null) {
            throw new CommandParser.ParseError(
                    "unknown verb \"" + name + "\"",
                    "verbs: " + String.join(" ", catalog.names())
            );
        }

        List args = new ArrayList<>();
        Map flags = new LinkedHashMap<>();
        int index = 1;
        while (index < tokens.size()) {
            String token = tokens.get(index);
            if (token.startsWith("--")) {
                index = longFlag(definition, tokens, index, flags);
            } else if (token.startsWith("-") && token.length() > 1
                    && !NUMERIC.matcher(token).matches()) {
                index = shortFlags(definition, tokens, index, flags);
            } else {
                args.add(token);
                index++;
            }
        }

        return new Ast.Invocation(
                name,
                List.copyOf(args),
                Collections.unmodifiableMap(new LinkedHashMap<>(flags))
        );
    }

    private int longFlag(
            VerbDefinition definition,
            List tokens,
            int index,
            Map flags
    ) {
        String body = tokens.get(index).substring(2);
        int equals = body.indexOf('=');
        String name = equals < 0 ? body : body.substring(0, equals);
        FlagSpec spec = find(definition, name, false);

        if (equals >= 0) {
            flags.put(spec.name(), body.substring(equals + 1));
            return index + 1;
        }

        Value result = value(spec, "--" + name, tokens, index);
        flags.put(spec.name(), result.text());
        return result.next();
    }

    private int shortFlags(
            VerbDefinition definition,
            List tokens,
            int index,
            Map flags
    ) {
        String group = tokens.get(index).substring(1);
        int next = index + 1;
        for (int offset = 0; offset < group.length(); offset++) {
            String name = String.valueOf(group.charAt(offset));
            FlagSpec spec = find(definition, name, true);
            if (spec.takesValue() && offset != group.length() - 1) {
                throw new CommandParser.ParseError(
                        "-" + name + " requires a value and must be at the end of the flag group",
                        null
                );
            }

            Value result = value(spec, "-" + name, tokens, index);
            flags.put(spec.name(), result.text());
            next = result.next();
        }
        return next;
    }

    private FlagSpec find(VerbDefinition definition, String name, boolean shortForm) {
        FlagSpec audit = FlagSpec.AUDIT;
        if (name.equals(shortForm ? audit.shortName() : audit.name())) {
            return audit;
        }
        for (FlagSpec spec : definition.options()) {
            if (name.equals(shortForm ? spec.shortName() : spec.name())) {
                return spec;
            }
        }

        List known = new ArrayList<>();
        known.add("--" + audit.name());
        for (FlagSpec spec : definition.options()) {
            known.add("--" + spec.name());
        }
        throw new CommandParser.ParseError(
                "unknown option " + (shortForm ? "-" : "--") + name + " for " + definition.name(),
                "options: " + String.join(", ", known)
        );
    }

    private record Value(String text, int next) {}

    private Value value(FlagSpec spec, String spelling, List tokens, int index) {
        if (!spec.takesValue()) {
            return new Value("", index + 1);
        }

        int next = index + 1;
        if (next < tokens.size() && !operandBreak(tokens.get(next))) {
            return new Value(tokens.get(next), next + 1);
        }
        if (spec.bareDefault() != null) {
            return new Value(spec.bareDefault(), next);
        }
        throw new CommandParser.ParseError(spelling + " requires a value", null);
    }

    private boolean operandBreak(String token) {
        return token.equals("|") || token.equals(";")
                || token.equals("&&") || token.equals("||") || token.startsWith("-");
    }
}



package com.archon.event;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;

/**
 * The single seam between simulation and presentation.
 * A graphical front end subscribes here instead of ConsoleView; no game code changes.
 */
public final class EventBus {
    private final List<Consumer> listeners = new ArrayList<>();

    public void subscribe(Consumer l) { listeners.add(l); }
    public void post(GameEvent e) { for (var l : listeners) l.accept(e); }

    public void narrate(String text) { post(new GameEvent.Narrative(text)); }
    public void redraw()             { post(new GameEvent.Redraw()); }
    public void audit(String text)   { post(new GameEvent.Audit(text)); }
}



package com.archon.event;

import com.archon.verb.ExitCode;
import java.util.List;

public sealed interface GameEvent {
    record RoundStart(int round, int ap)                                              implements GameEvent {}
    record RoundEnd(int wasted, List worldLog)                                implements GameEvent {}
    record Rejected(ExitCode code, String reason, String hint)                        implements GameEvent {}
    record LineStart(String raw, int lineNo, int allocation, int tax, boolean chain)   implements GameEvent {}
    record StageResult(int index, int total, String render, ExitCode code,
                       int charged, int apLeft)                                       implements GameEvent {}
    record StageSkipped(int index, String render, String why)                          implements GameEvent {}
    record LineComplete(int charged, int tax, int returnedUnused, int apLeft)          implements GameEvent {}
    record LineBroke(int stageIndex, String reason, int allocation, int penalty,
                     int forfeited, int apLeft, String hint)                          implements GameEvent {}
    record InterruptFired(String source, String description, int damage)               implements GameEvent {}
    record Narrative(String text)                                                     implements GameEvent {}
    record Audit(String text)                                                         implements GameEvent {}
    record Redraw()                                                                   implements GameEvent {}
    record ThrallDied()                                                               implements GameEvent {}
}



package com.archon.exec;

public record EconomyRules(
        int roundAp,
        int untaxedLines,
        int lineTax,
        int breakPenalty
) {
    public EconomyRules {
        if (roundAp <= 0 || untaxedLines < 0 || lineTax < 0 || breakPenalty < 0) {
            throw new IllegalArgumentException(
                    "round AP must be positive; other economy values must not be negative");
        }
    }

    public static EconomyRules prototype() {
        return new EconomyRules(5, 1, 1, 1);
    }

    public int taxForNextLine(int linesUsed) {
        return nonNegative(linesUsed, "lines used") < untaxedLines ? 0 : lineTax;
    }

    public int interruptedCharge(int stageCost) {
        return nonNegative(stageCost, "stage cost") / 2;
    }

    public int breakCharge(int allocation, int availableAp) {
        return (int) Math.min((long) nonNegative(allocation, "allocation") + breakPenalty,
                nonNegative(availableAp, "available AP"));
    }

    private static int nonNegative(int value, String name) {
        if (value < 0) {
            throw new IllegalArgumentException(name + " must not be negative");
        }
        return value;
    }
}



package com.archon.exec;

import com.archon.command.Ast;
import com.archon.verb.VerbCatalog;

import java.util.Objects;

public final class ExecutionPolicy {

    private final VerbCatalog catalog;

    public ExecutionPolicy(VerbCatalog catalog) {
        this.catalog = Objects.requireNonNull(catalog, "catalog");
    }

    /** A material pipeline costs only its final invocation. */
    public int stageCost(Ast.Stage stage) {
        return Objects.requireNonNull(catalog.get(stage.last().verb()), "unknown verb").price().cost(stage.last());
    }

    public boolean paidStage(Ast.Stage stage) {
        return stage.pipeline().stream().anyMatch(
                invocation -> !Objects.requireNonNull(catalog.get(invocation.verb()), "unknown verb").free());
    }

    public SubmissionQuote quote(Ast.Line line, RoundState round) {
        boolean free = line.stages().stream().noneMatch(this::paidStage);
        int allocation = line.stages().stream().mapToInt(this::stageCost).reduce(0, Math::addExact);
        return new SubmissionQuote(free, allocation, round);
    }
}



package com.archon.exec;

import com.archon.event.EventBus;
import com.archon.event.GameEvent;
import com.archon.system.combat.Reaction;

import java.util.Objects;
import java.util.Optional;
import java.util.function.Supplier;

/** Resolves one reaction and publishes the facts captured by that resolution. */
public final class Interrupts {

    private final Supplier<Optional> resolve;
    private final EventBus bus;

    public Interrupts(Supplier<Optional> resolve, EventBus bus) {
        this.resolve = Objects.requireNonNull(resolve, "resolve");
        this.bus = Objects.requireNonNull(bus, "bus");
    }

    public Optional fire() {
        Optional reaction = Objects.requireNonNull(resolve.get(), "reaction result");
        reaction.ifPresent(result -> bus.post(
                new GameEvent.InterruptFired(result.sourceId(), result.description(), result.damage())));
        return reaction;
    }
}



