package com.archon.command;

import java.util.LinkedHashMap;
import java.util.Map;

public record FlagSpec(
        String name,
        String shortName,
        String valueName,
        String bareDefault,
        String description
) {
    public static final FlagSpec AUDIT = new FlagSpec(
            "dry-run", "n", null, null, "Audit the entire line without executing or spending AP.");

    public FlagSpec {
        java.util.Objects.requireNonNull(description, "description");
        if (name == null || !name.matches("[a-z][a-z0-9-]*")) {
            throw new IllegalArgumentException("invalid option name: " + name);
        }
        if (shortName != null && !shortName.matches("[A-Za-z]")) {
            throw new IllegalArgumentException("short option must be one letter");
        }
        if (valueName != null && valueName.isBlank()) {
            throw new IllegalArgumentException("option value name must not be blank");
        }
        if (valueName == null && bareDefault != null) {
            throw new IllegalArgumentException("boolean option cannot have a value default");
        }
    }

    public boolean takesValue() { return valueName != null; }
}



package com.archon.exec;

import com.archon.command.Ast;
import com.archon.verb.ExitCode;
import com.archon.verb.Material;

import java.util.Objects;

public final class PipelineRunner {
    public record Result(ExitCode code, boolean paidExecuted, boolean terminalExecuted) {}

    private final InvocationRunner invocations;

    public PipelineRunner(InvocationRunner invocations) {
        this.invocations = Objects.requireNonNull(invocations, "invocations");
    }

    public Result runStage(Ast.Stage stage) {
        Material material = null;
        boolean paid = false;
        boolean terminal = false;

        for (int i = 0; i < stage.pipeline().size(); i++) {
            InvocationRunner.Result result = invocations.run(
                    stage.pipeline().get(i), material, i > 0);
            paid |= result.paid();
            terminal |= result.terminal();
            if (result.code() != ExitCode.SUCCESS) {
                return new Result(result.code(), paid, terminal);
            }
            material = result.output();
        }
        return new Result(ExitCode.SUCCESS, paid, terminal);
    }
}



package com.archon.exec;

public final class RoundState {
    private final EconomyRules rules;
    private int ap;
    private int linesUsed = 0;
    private int roundNo = 1;

    public RoundState(EconomyRules rules) {
        this.rules = java.util.Objects.requireNonNull(rules, "rules");
        ap = rules.roundAp();
    }

    public EconomyRules rules() {
        return rules;
    }

    public int ap() {
        return ap;
    }

    public int linesUsed() {
        return linesUsed;
    }

    public int roundNo() {
        return roundNo;
    }

    public void spend(int amount) {
        if (amount < 0 || amount > ap) {
            throw new IllegalArgumentException("spending must be between 0 and " + ap + ": " + amount);
        }
        ap -= amount;
    }

    public void countLine() {
        linesUsed = Math.incrementExact(linesUsed);
    }

    public int reset() {
        roundNo = Math.incrementExact(roundNo);
        int wasted = ap;
        ap = rules.roundAp();
        linesUsed = 0;
        return wasted;
    }
}



package com.archon.exec;

import com.archon.command.Ast;
import com.archon.model.World;
import com.archon.verb.*;

import java.util.Objects;
import java.util.Set;

public final class Validator {

    private final World world;
    private final VerbCatalog catalog;

    public Validator(World world, VerbCatalog catalog) {
        this.world = Objects.requireNonNull(world, "world");
        this.catalog = Objects.requireNonNull(catalog, "catalog");
    }

    public Check validate(Ast.Line line) {
        for (int s = 0; s < line.stages().size(); s++) {
            Ast.Stage stage = line.stages().get(s);
            Set inputKinds = Set.of();

            for (int p = 0; p < stage.pipeline().size(); p++) {
                Ast.Invocation inv = stage.pipeline().get(p);
                VerbDefinition definition = catalog.get(inv.verb());

                if (definition == null) return Check.invalid("unknown verb \"" + inv.verb() + "\"",
                        "verbs: " + String.join(" ", catalog.names()));

                if (definition.terminal() && (s != line.stages().size() - 1 || p != stage.pipeline().size() - 1))
                    return Check.invalid("\"" + inv.verb() + "\" must be the final command",
                            "terminal verbs cannot be chained further");

                if (p < stage.pipeline().size() - 1 && definition.output().isEmpty())
                    return Check.invalid("\"" + inv.verb() + "\" produces nothing to pipe",
                            "use a material-producing verb before |");

                if (p > 0 && !definition.input().containsAll(inputKinds))
                    return Check.invalid("\"" + inv.verb() + "\" cannot receive all producer material kinds",
                            "producer: " + inputKinds + "; accepted: " + definition.input());

                Check check = definition.action().validateStructural(new ValidationContext(world, inv, p > 0, null));
                if (!check.valid()) {
                    if (check.code() != ExitCode.INVALID) {
                        throw new IllegalStateException("submission validation returned a gameplay failure");
                    }
                    return check;
                }
                inputKinds = definition.output();
            }
        }
        return Check.ok();
    }
}



