package com.archon.verb;

import com.archon.address.Resolved;
import com.archon.model.Actor;
import com.archon.model.ItemLocation;

final class VerbTargets {
    private VerbTargets() {}

    static Check resolution(Resolved resolved) {
        if (!(resolved instanceof Resolved.Failure failure)) {
            return Check.ok();
        }

        return switch (failure.problem()) {
            case BAD_SYNTAX, INVALID_TILE ->
                    Check.invalid(failure.reason(), null);
            case UNKNOWN_ENTITY, DEAD_ENTITY, ITEM_NOT_FOUND, UNSUPPORTED_PATH, OUT_OF_BOUNDS ->
                    Check.blocked(failure.reason(), null);
        };
    }

    static Check reachable(ValidationContext c, Resolved.Target target) {
        return target.pos().chebyshev(c.thrall.pos()) <= 1
                ? Check.ok()
                : Check.blocked(
                "target at " + target.pos() + " out of reach",
                "step closer first"
        );
    }

    static boolean ownedBy(ItemLocation location, Actor actor) {
        return switch (location) {
            case ItemLocation.Pack pack -> pack.owner() == actor;
            case ItemLocation.Equipment equipment -> equipment.owner() == actor;
            case ItemLocation.Contents ignored -> false;
            case ItemLocation.Ground ignored -> false;
        };
    }

    static ExitCode reject(VerbContext c, Check check) {
        c.say(check.reason());
        return check.code();
    }
}



package com.archon.command;

import java.util.List;
import java.util.Map;
public final class Ast {
    private Ast() {}

    public enum Op { NONE, SEQ, AND, OR }

    public record Invocation(String verb, List args, Map flags) {
        public String flag(String name) { return flags.get(name); }
        public boolean hasFlag(String name) { return flags.containsKey(name); }
        public String arg(int i) { return i < args.size() ? args.get(i) : null; }
        public String render() {
            StringBuilder sb = new StringBuilder(verb);
            args.forEach(a -> sb.append(' ').append(a));
            flags.forEach((k, v) -> sb.append(" --").append(k).append(v.isEmpty() ? "" : "=" + v));
            return sb.toString();
        }
    }

    /** One unit between ;, && and ||. A pipeline of one or more invocations. */
    public record Stage(List pipeline, Op op) {
        public Invocation last() { return pipeline.get(pipeline.size() - 1); }
        public String render() {
            return String.join(" | ", pipeline.stream().map(Invocation::render).toList());
        }
    }

    public record Line(List stages, boolean dryRun, String raw) {
        public int verbCount() { return stages.stream().mapToInt(s -> s.pipeline().size()).sum(); }
        public boolean isChain() { return verbCount() >= 2; }
    }
}



package com.archon.model;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.Objects;

/** A creature with strength, equipment, carried items, and ranged-weapon state. */
public class Actor extends Entity {
    public enum Trigger {
        ON_ADJACENCY,
        ON_MOVEMENT_IN_LOS
    }

    public record Readied(Trigger trigger, String description, int damage) {
        public Readied {
            Objects.requireNonNull(trigger, "trigger");
            if (description == null || description.isBlank()) {
                throw new IllegalArgumentException("description must not be blank");
            }
            if (damage < 0) {
                throw new IllegalArgumentException("damage must be nonnegative");
            }
        }
    }

    private final Inventory inventory = new Inventory();
    private final EnumMap crippled = new EnumMap<>(BodyPart.class);
    private final int strength;
    private Readied readied;
    private boolean readiedSpent;
    private boolean guarded;
    private boolean nocked;

    public Actor(String id, String name, char glyph, Vec2 pos, CreatureStats stats) {
        this(validatedStats(stats), id, name, glyph, pos);
    }

    private Actor(CreatureStats stats, String id, String name, char glyph, Vec2 pos) {
        super(
                id,
                name,
                glyph,
                Kind.CREATURE,
                pos,
                stats.maxHp(),
                stats.armor(),
                stats.evasion());
        this.strength = stats.strength();

        for (BodyPart bodyPart : BodyPart.values()) {
            crippled.put(bodyPart, false);
        }
    }

    private static CreatureStats validatedStats(CreatureStats stats) {
        return Objects.requireNonNull(stats, "creature stats cannot be null");
    }

    public Inventory inventory() {
        return inventory;
    }

    public Map crippled() {
        return Collections.unmodifiableMap(crippled);
    }

    public int strength() {
        return strength;
    }

    public boolean isGuarded() {
        return guarded;
    }

    public Readied readied() {
        return readied;
    }

    public boolean isReadiedSpent() {
        return readiedSpent;
    }

    public Actor ready(Trigger trigger, String description, int damage) {
        readied = new Readied(trigger, description, damage);
        readiedSpent = false;
        return this;
    }

    public void setGuarded(boolean guarded) {
        this.guarded = guarded;
    }

    public void spendReadied() {
        readiedSpent = true;
    }

    public void resetRoundState() {
        readiedSpent = false;
        guarded = false;
    }

    public boolean isNocked() {
        return nocked;
    }

    public void nock() {
        nocked = true;
    }

    public boolean fireNocked() {
        if (!nocked) {
            return false;
        }
        nocked = false;
        return true;
    }

    /** Right hand has priority for melee attacks. */
    public Item mainHand() {
        Item right = inventory.equipped(EquipmentSlot.HAND_RIGHT);
        return right != null ? right : inventory.equipped(EquipmentSlot.HAND_LEFT);
    }

    public Item disarm(EquipmentSlot slot) {
        return inventory.removeEquipped(slot);
    }
}



package com.archon.model;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;

/**
 * Encapsulates the spatial 2D grid of tiles, boundary validation, and tile mutation.
 */
public final class GameMap {
    private final int width;
    private final int height;
    private final Tile[][] tiles;

    public GameMap(int width, int height) {
        if (width <= 0 || height <= 0) {
            throw new IllegalArgumentException("Map dimensions must be positive");
        }

        this.width = width;
        this.height = height;
        this.tiles = new Tile[height][width];

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                tiles[y][x] = new Tile();
            }
        }
    }

    public int width() {
        return width;
    }

    public int height() {
        return height;
    }

    public boolean inBounds(Vec2 position) {
        return position != null
                && position.x() >= 0
                && position.y() >= 0
                && position.x() < width
                && position.y() < height;
    }

    public Tile tile(Vec2 position) {
        return inBounds(position) ? tiles[position.y()][position.x()] : null;
    }

    public void setWall(Vec2 position, boolean wall) {
        requireTile(position).wall = wall;
    }

    public void addTag(Vec2 position, Tag tag) {
        requireTile(position).tags.add(Objects.requireNonNull(tag, "tag"));
    }

    public boolean removeTag(Vec2 position, Tag tag) {
        return requireTile(position).tags.remove(Objects.requireNonNull(tag, "tag"));
    }

    public void addCeilingTag(Vec2 position, Tag tag) {
        requireTile(position).ceiling.add(Objects.requireNonNull(tag, "tag"));
    }

    public boolean removeCeilingTag(Vec2 position, Tag tag) {
        return requireTile(position).ceiling.remove(Objects.requireNonNull(tag, "tag"));
    }

    public void placeGroundItem(Vec2 position, Item item) {
        requireTile(position).ground.add(Objects.requireNonNull(item, "item"));
    }

    public boolean removeGroundItem(Vec2 position, Item item) {
        return requireTile(position).ground.remove(Objects.requireNonNull(item, "item"));
    }

    public Item removeFirstGroundItem(Vec2 position) {
        Tile tile = requireTile(position);
        return tile.ground.isEmpty() ? null : tile.ground.remove(0);
    }

    private Tile requireTile(Vec2 position) {
        Objects.requireNonNull(position, "position");
        if (!inBounds(position)) {
            throw new IllegalArgumentException("Position is outside the map: " + position);
        }
        return tiles[position.y()][position.x()];
    }

    public static final class Tile {
        private boolean wall;
        private final EnumSet tags;
        private final EnumSet ceiling;
        private final ArrayList
 ground;
        private final Set tagsView;
        private final Set ceilingView;
        private final List
 groundView;

        private Tile() {
            tags = EnumSet.noneOf(Tag.class);
            ceiling = EnumSet.noneOf(Tag.class);
            ground = new ArrayList<>();
            tagsView = Collections.unmodifiableSet(tags);
            ceilingView = Collections.unmodifiableSet(ceiling);
            groundView = Collections.unmodifiableList(ground);
        }

        public boolean isWall() {
            return wall;
        }

        public boolean has(Tag tag) {
            return tags.contains(Objects.requireNonNull(tag, "tag"));
        }

        public Set tags() {
            return tagsView;
        }

        public Set ceiling() {
            return ceilingView;
        }

        public List
 ground() {
            return groundView;
        }
    }
}



package com.archon.app;

import com.archon.event.EventBus;
import com.archon.event.GameEvent;
import com.archon.exec.EconomyRules;
import com.archon.exec.Executor;
import com.archon.exec.RoundState;
import com.archon.model.Dice;
import com.archon.model.World;
import com.archon.ui.ConsoleView;

import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public final class Repl {

    private final Map aliases = new HashMap<>();
    private String lastLine = "";

    public void run(long seed) {
        World world = Scenario.testRoom(new Dice.Seeded(seed));
        EventBus bus = new EventBus();
        ConsoleView view = new ConsoleView();
        bus.subscribe(view::handle);

        RoundState round = new RoundState(EconomyRules.prototype());
        Executor exec = ExecutionSetup.create(world, bus, round);

        bus.post(new GameEvent.RoundStart(round.roundNo(), round.ap()));
        bus.narrate("Type 'help'. Free commands never cost AP or count as a line.");
        view.frame(world, round);

        Scanner in = new Scanner(System.in);
        while (true) {
            System.out.print("ARCHON> ");
            if (!in.hasNextLine()) break;
            String raw = in.nextLine().trim();

            if (raw.equalsIgnoreCase("quit") || raw.equalsIgnoreCase("exit")) break;
            if (raw.isEmpty() || raw.equals("!!")) raw = lastLine;
            if (raw.isEmpty()) continue;

            if (raw.startsWith("alias ")) {
                defineAlias(raw, bus);
                view.frame(world, round);
                continue;
            }
            raw = expandAliases(raw);
            lastLine = raw;

            Executor.Outcome o = exec.submit(raw);

            if (!world.thrall().alive()) {
                view.frame(world, round);
                System.out.println("Run over.");
                break;
            }

            if (o.roundOver()) {
                exec.endRound();
            }
            view.frame(world, round);
        }
    }

    private void defineAlias(String raw, EventBus bus) {
        String body = raw.substring(6).trim();
        int eq = body.indexOf('=');
        if (eq < 0) {
            bus.narrate("usage: alias k=\"strike -p heavy\"");
            return;
        }
        String name = body.substring(0, eq).trim();
        String value = body.substring(eq + 1).trim().replaceAll("^\"|\"$", "");
        aliases.put(name, value);
        bus.narrate("alias " + name + " -> " + value);
    }

    /**
     * Expansion happens before parsing, so verb count and allocation are computed post-expansion.
     */
    private String expandAliases(String raw) {
        String out = raw;
        for (int depth = 0; depth < 5; depth++) {
            String[] parts = out.split("(?=\\s*(;|&&|\\|\\||\\|))");
            StringBuilder sb = new StringBuilder();
            boolean changed = false;
            for (String part : parts) {
                String trimmed = part.stripLeading();
                String lead = part.substring(0, part.length() - trimmed.length());
                String[] toks = trimmed.split("\\s+", 2);
                String head = toks.length > 0 ? toks[0].replaceAll("^(;|&&|\\|\\||\\|)\\s*", "") : "";
                String opPrefix = toks.length > 0 ? toks[0].substring(0, toks[0].length() - head.length()) : "";
                if (aliases.containsKey(head)) {
                    changed = true;
                    sb.append(lead).append(opPrefix).append(aliases.get(head));
                    if (toks.length > 1) sb.append(' ').append(toks[1]);
                } else sb.append(part);
            }
            out = sb.toString();
            if (!changed) break;
        }
        return out;
    }
}



package com.archon.command;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

public final class CommandParser {

    private final InvocationParser invocations;

    public CommandParser(InvocationParser invocations) {
        this.invocations = Objects.requireNonNull(invocations, "invocations");
    }

    public static final class ParseError extends RuntimeException {
        public final String hint;

        public ParseError(String msg, String hint) {
            super(msg);
            this.hint = hint;
        }
    }

    public Ast.Line parse(String raw) {
        List tokens = lex(raw);
        if (tokens.isEmpty()) return new Ast.Line(List.of(), false, raw);

        List stages = new ArrayList<>();
        List pipeline = new ArrayList<>();
        List current = new ArrayList<>();
        Ast.Op pendingOp = Ast.Op.NONE;
        boolean dryRun = false;

        for (String token : tokens) {
            boolean pipe = "|".equals(token);
            boolean separator = ";".equals(token) || "&&".equals(token) || "||".equals(token);

            if (pipe || separator) {
                if (current.isEmpty()) {
                    throw new ParseError("operator with no command",
                            "every operator must sit between two commands");
                }
                Ast.Invocation invocation = invocations.parse(current);
                if (invocation.hasFlag(FlagSpec.AUDIT.name())) dryRun = true;
                pipeline.add(invocation);
                current.clear();

                if (separator) {
                    stages.add(new Ast.Stage(List.copyOf(pipeline), pendingOp));
                    pipeline.clear();
                    pendingOp = switch (token) {
                        case "&&" -> Ast.Op.AND;
                        case "||" -> Ast.Op.OR;
                        default -> Ast.Op.SEQ;
                    };
                }
            } else {
                current.add(token);
            }
        }

        if (!current.isEmpty()) {
            Ast.Invocation invocation = invocations.parse(current);
            if (invocation.hasFlag(FlagSpec.AUDIT.name())) dryRun = true;
            pipeline.add(invocation);
        } else if (!pipeline.isEmpty() || pendingOp != Ast.Op.NONE) {
            throw new ParseError("operator with no command",
                    "a command line cannot end with an operator or pipe");
        }

        if (!pipeline.isEmpty()) {
            stages.add(new Ast.Stage(List.copyOf(pipeline), pendingOp));
        }
        return new Ast.Line(List.copyOf(stages), dryRun, raw);
    }

    private List lex(String raw) {
        List out = new ArrayList<>();
        StringBuilder sb = new StringBuilder();
        boolean quoted = false;

        for (int i = 0; i < raw.length(); i++) {
            char c = raw.charAt(i);
            if (c == '"') {
                quoted = !quoted;
                continue;
            }
            if (quoted) {
                sb.append(c);
                continue;
            }
            if (Character.isWhitespace(c)) {
                flush(out, sb);
                continue;
            }
            if (c == ';' || c == '|' || c == '&') {
                flush(out, sb);
                if ((c == '|' || c == '&') && i + 1 < raw.length() && raw.charAt(i + 1) == c) {
                    out.add("" + c + c);
                    i++;
                } else {
                    out.add(String.valueOf(c));
                }
                continue;
            }
            sb.append(c);
        }

        if (quoted) throw new ParseError("unbalanced quote", null);
        flush(out, sb);
        return out;
    }

    private void flush(List out, StringBuilder sb) {
        if (!sb.isEmpty()) {
            out.add(sb.toString());
            sb.setLength(0);
        }
    }
}



package com.archon.exec;

import com.archon.command.Ast;
import com.archon.command.CommandParser;
import com.archon.event.EventBus;
import com.archon.event.GameEvent;
import com.archon.model.World;
import com.archon.verb.Check;
import com.archon.verb.ExitCode;

import java.util.List;
import java.util.Objects;
import java.util.function.Supplier;

public final class Executor {

    public enum Kind {NOOP, FREE, AUDIT, REJECTED, COMPLETE, BROKE}

    public record Outcome(
            Kind kind, ExitCode lastCode, int tax, int allocation,
            int charged, int forfeited, int apAfter, int linesUsed,
            boolean roundOver) {}

    private final World world;
    private final EventBus bus;
    private final RoundState round;
    private final CommandParser parser;
    private final SubmissionChecks submissions;
    private final Auditor auditor;
    private final StageRunner stageRunner;
    private final SettlementManager settlementManager;
    private final Supplier<List> tick;

    public Executor(
            World world,
            EventBus bus,
            RoundState round,
            CommandParser parser,
            SubmissionChecks submissions,
            Auditor auditor,
            StageRunner stageRunner,
            SettlementManager settlementManager,
            Supplier<List> tick
    ) {
        this.world = Objects.requireNonNull(world, "world");
        this.bus = Objects.requireNonNull(bus, "bus");
        this.round = Objects.requireNonNull(round, "round");
        this.parser = Objects.requireNonNull(parser, "parser");
        this.submissions = Objects.requireNonNull(submissions, "submissions");
        this.auditor = Objects.requireNonNull(auditor, "auditor");
        this.stageRunner = Objects.requireNonNull(stageRunner, "stageRunner");
        this.settlementManager = Objects.requireNonNull(settlementManager, "settlementManager");
        this.tick = Objects.requireNonNull(tick, "tick");
    }

    public RoundState round() {
        return round;
    }

    public Outcome submit(String raw) {
        Ast.Line line;
        try {
            line = parser.parse(raw);
        } catch (CommandParser.ParseError error) {
            bus.post(new GameEvent.Rejected(ExitCode.INVALID, error.getMessage(), error.hint));
            return out(Kind.REJECTED, ExitCode.INVALID, 0, 0);
        }
        if (line.stages().isEmpty()) {
            return out(Kind.NOOP, ExitCode.SUCCESS, 0, 0);
        }
        if (line.dryRun()) {
            SubmissionChecks.Review review = auditor.audit(line);
            return out(Kind.AUDIT, review.check().code(), 0,
                    review.quote() == null ? 0 : review.quote().allocation());
        }

        SubmissionChecks.Review review = submissions.review(line);
        SubmissionQuote quote = review.quote();
        if (!review.check().valid()) {
            Check check = review.check();
            bus.post(new GameEvent.Rejected(check.code(), check.reason(), check.hint()));
            return out(Kind.REJECTED, check.code(),
                    quote == null ? 0 : quote.tax(), quote == null ? 0 : quote.allocation());
        }

        if (!quote.free()) {
            round.spend(quote.tax());
            round.countLine();
            world.resetThrallMovement();
            bus.post(new GameEvent.LineStart(
                    line.raw(), round.linesUsed(), quote.allocation(), quote.tax(), line.isChain()));
        }
        return settlementManager.settle(quote, stageRunner.execute(line, round));
    }

    public void endRound() {
        int wasted = round.ap();
        List worldLog = tick.get();
        round.reset();
        bus.post(new GameEvent.RoundEnd(wasted, worldLog));
        bus.post(new GameEvent.RoundStart(round.roundNo(), round.ap()));
    }

    private Outcome out(Kind kind, ExitCode code, int tax, int allocation) {
        return new Outcome(
                kind, code, tax, allocation, 0, 0, round.ap(), round.linesUsed(), false);
    }
}



package com.archon.exec;

import com.archon.event.EventBus;
import com.archon.event.GameEvent;
import com.archon.model.World;

import java.util.Objects;
import java.util.Optional;

public final class SettlementManager {
    private final World world;
    private final EventBus bus;
    private final RoundState round;
    private final Interrupts interrupts;

    public SettlementManager(World world, EventBus bus, RoundState round, Interrupts interrupts) {
        this.world = Objects.requireNonNull(world, "world");
        this.bus = Objects.requireNonNull(bus, "bus");
        this.round = Objects.requireNonNull(round, "round");
        this.interrupts = Objects.requireNonNull(interrupts, "interrupts");
    }

    public Executor.Outcome settle(SubmissionQuote quote, ExecutionTrace trace) {
        Optional interruption = trace.interruption();
        boolean broke = interruption.isPresent();
        int charged = trace.charged();
        int forfeited = 0;

        if (broke) {
            ExecutionTrace.Stage stage = interruption.orElseThrow();
            forfeited = quote.free() ? 0 : round.rules().breakCharge(quote.allocation(), round.ap());
            round.spend(forfeited);
            bus.post(new GameEvent.LineBroke(stage.index(), stage.reason(), quote.allocation(),
                    quote.free() ? 0 : round.rules().breakPenalty(), forfeited, round.ap(), null));
        } else if (!quote.free()) {
            round.spend(charged);
            if (trace.paidExecuted() && world.thrall().alive()) {
                interrupts.fire();
            }
            bus.post(new GameEvent.LineComplete(charged, quote.tax(), quote.allocation() - charged, round.ap()));
        }

        boolean alive = world.thrall().alive();
        if (!alive) {
            bus.post(new GameEvent.ThrallDied());
        }
        boolean roundOver = alive && ((!quote.free() && round.ap() == 0) || (!broke && trace.terminalExecuted()));
        Executor.Kind kind = broke ? Executor.Kind.BROKE : quote.free() ? Executor.Kind.FREE : Executor.Kind.COMPLETE;
        return new Executor.Outcome(kind, trace.lastCode(), quote.tax(), quote.allocation(), charged, forfeited,
                round.ap(), round.linesUsed(), roundOver);
    }
}



package com.archon.exec;

import com.archon.command.Ast;
import com.archon.event.EventBus;
import com.archon.event.GameEvent;
import com.archon.system.combat.Reaction;
import com.archon.verb.ExitCode;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

public final class StageRunner {
    private final EventBus bus;
    private final PipelineRunner pipelineRunner;
    private final ExecutionPolicy policy;
    private final Interrupts interrupts;

    public StageRunner(EventBus bus, PipelineRunner pipelineRunner, ExecutionPolicy policy, Interrupts interrupts) {
        this.bus = Objects.requireNonNull(bus, "bus");
        this.pipelineRunner = Objects.requireNonNull(pipelineRunner, "pipelineRunner");
        this.policy = Objects.requireNonNull(policy, "policy");
        this.interrupts = Objects.requireNonNull(interrupts, "interrupts");
    }

    public ExecutionTrace execute(Ast.Line line, RoundState round) {
        List results = new ArrayList<>();
        ExitCode last = ExitCode.SUCCESS;
        int charged = 0;
        boolean paidExecuted = false;
        boolean stopped = false;

        for (int i = 0; i < line.stages().size(); i++) {
            Ast.Stage stage = line.stages().get(i);
            int cost = policy.stageCost(stage);
            if (stopped) {
                results.add(
                        new ExecutionTrace.Stage(i + 1, ExecutionTrace.State.NOT_REACHED, null, cost, 0, false, false,
                                "line interrupted"));
                continue;
            }

            boolean run = switch (stage.op()) {
                case AND -> last == ExitCode.SUCCESS;
                case OR -> last != ExitCode.SUCCESS;
                default -> true;
            };
            if (!run) {
                String reason = stage.op() == Ast.Op.AND ? "&& requires SUCCESS" : "|| requires ordinary failure";
                results.add(new ExecutionTrace.Stage(i + 1, ExecutionTrace.State.SKIPPED, null, cost, 0, false, false,
                        reason));
                bus.post(new GameEvent.StageSkipped(i + 1, stage.render(), reason));
                continue;
            }

            Reaction reaction = paidExecuted && policy.paidStage(stage) ? interrupts.fire().orElse(null) : null;
            if (reaction != null) {
                results.add(new ExecutionTrace.Stage(i + 1, ExecutionTrace.State.INTERRUPTED_BEFORE, ExitCode.INTERRUPT,
                        cost, round.rules().interruptedCharge(cost), false, false,
                        reaction.sourceName() + " (READIED) interrupted the sequence"));
                stopped = true;
                continue;
            }

            PipelineRunner.Result result = pipelineRunner.runStage(stage);
            last = result.code();
            paidExecuted |= result.paidExecuted();
            stopped = last == ExitCode.INTERRUPT;
            int charge = stopped ? round.rules().interruptedCharge(cost) : cost;
            charged += charge;
            results.add(new ExecutionTrace.Stage(i + 1,
                    stopped ? ExecutionTrace.State.INTERRUPTED_DURING : ExecutionTrace.State.EXECUTED, last, cost,
                    charge, result.paidExecuted(), result.terminalExecuted(),
                    stopped ? "interrupted during stage " + (i + 1) : null));
            if (!stopped) {
                bus.post(new GameEvent.StageResult(i + 1, line.stages().size(), stage.render(), last, charge,
                        round.ap() - charged));
            }
        }
        return new ExecutionTrace(results);
    }
}



package com.archon.model;

import java.util.Collections;
import java.util.EnumSet;
import java.util.Objects;
import java.util.Set;

public final class Item {
    private final String id;
    private final String name;
    private final Set tags;
    private Tag substance;
    private int durability;
    private final int damage;

    public Item(String id, String name, Set tags, Tag substance, int durability, int damage) {
        this.id = Objects.requireNonNull(id, "id cannot be null");
        if (id.isBlank()) {
            throw new IllegalArgumentException("id cannot be blank");
        }

        this.name = Objects.requireNonNull(name, "name cannot be null");
        if (name.isBlank()) {
            throw new IllegalArgumentException("name cannot be blank");
        }

        Objects.requireNonNull(tags, "tags cannot be null");
        if (durability < 0) {
            throw new IllegalArgumentException("durability cannot be negative");
        }
        if (damage < 0) {
            throw new IllegalArgumentException("damage cannot be negative");
        }

        EnumSet copiedTags = EnumSet.noneOf(Tag.class);
        copiedTags.addAll(tags);
        this.tags = copiedTags;
        this.substance = substance;
        this.durability = durability;
        this.damage = damage;
    }

    public static Item weapon(String id, String name, int damage, int durability, Tag... tags) {
        EnumSet itemTags = EnumSet.noneOf(Tag.class);
        if (tags != null) {
            Collections.addAll(itemTags, tags);
        }
        return new Item(id, name, itemTags, null, durability, damage);
    }

    public static Item flask(String id, String name, Tag substance) {
        return new Item(id, name, EnumSet.of(Tag.GLASS, Tag.BREAKABLE), substance, 1, 0);
    }

    public String id() {
        return id;
    }

    public String name() {
        return name;
    }

    public Set tags() {
        return Collections.unmodifiableSet(tags);
    }

    public Tag substance() {
        return substance;
    }

    public int durability() {
        return durability;
    }

    public int damage() {
        return damage;
    }

    public boolean has(Tag tag) {
        return tags.contains(tag);
    }

    public Tag consumeSubstance() {
        Tag value = substance;
        substance = null;
        return value;
    }

    public void wear(int amount) {
        if (amount < 0) {
            throw new IllegalArgumentException("wear cannot be negative");
        }
        durability = Math.max(0, durability - amount);
    }

    @Override
    public String toString() {
        return id;
    }
}



package com.archon.system.spatial;

import com.archon.model.Entity;
import com.archon.model.GameMap;
import com.archon.model.Vec2;
import com.archon.model.World;

import java.util.List;

/**
 * Domain service encapsulating geometry, raycasting (line of sight),
 * map passability, and entity occupancy checks.
 */
public final class SpatialService {

    private SpatialService() {}

    public static Entity entityAt(World world, Vec2 p) {
        if (world.thrall() != null && world.thrall().pos().equals(p)) return world.thrall();
        return world.entities().stream()
                .filter(e -> e.alive() && e.pos().equals(p))
                .findFirst()
                .orElse(null);
    }

    public static boolean passable(World world, Vec2 p) {
        GameMap.Tile tile = world.tile(p);
        return tile != null && !tile.isWall() && entityAt(world, p) == null;
    }

    public static List hostilesAdjacentTo(World world, Vec2 p) {
        return world.entities().stream()
                .filter(e -> e.alive() && e.kind() == Entity.Kind.CREATURE)
                .filter(e -> e.pos().chebyshev(p) <= 1)
                .toList();
    }

    public static boolean lineOfSight(GameMap map, Vec2 a, Vec2 b) {
        int dx = Math.abs(b.x() - a.x());
        int dy = Math.abs(b.y() - a.y());
        int sx = a.x() < b.x() ? 1 : -1;
        int sy = a.y() < b.y() ? 1 : -1;
        int err = dx - dy;
        int x = a.x();
        int y = a.y();

        while (x != b.x() || y != b.y()) {
            int e2 = 2 * err;
            if (e2 > -dy) {
                err -= dy;
                x += sx;
            }
            if (e2 < dx) {
                err += dx;
                y += sy;
            }
            if (x == b.x() && y == b.y()) break;

            GameMap.Tile tile = map.tile(new Vec2(x, y));
            if (tile == null || tile.isWall()) return false;
        }

        return true;
    }

    public static boolean lineOfSight(World world, Vec2 a, Vec2 b) {
        return lineOfSight(world.map(), a, b);
    }
}



package com.archon.verb;

import com.archon.command.FlagSpec;
import com.archon.exec.EconomyRules;

import java.util.*;
import java.util.stream.Collectors;

public final class CommandManual {

    private static final List TOPICS =
            List.of("operators", "address", "economy", "flags");

    private final EconomyRules rules;
    private VerbCatalog catalog;

    public CommandManual(EconomyRules rules) {
        this.rules = Objects.requireNonNull(rules, "rules");
    }

    /** Composition-only initialization, before this manual is published for use. */
    public void bind(VerbCatalog catalog) {
        Objects.requireNonNull(catalog, "catalog");
        if (this.catalog != null) {
            throw new IllegalStateException("command manual is already bound");
        }
        this.catalog = catalog;
    }

    /** Null or blank selects the index. Unknown queries return a diagnostic. */
    public String render(String query) {
        if (catalog == null) {
            throw new IllegalStateException("command manual has not been bound");
        }
        if (query == null || query.isBlank()) {
            return renderIndex();
        }

        String name = query.strip().toLowerCase(Locale.ROOT);
        VerbDefinition definition = catalog.get(name);
        if (definition != null) {
            return renderVerb(definition);
        }

        String topic = switch (name) {
            case "operators" -> operators();
            case "address" -> addressing();
            case "economy" -> economy();
            case "flags" -> flags();
            default -> null;
        };
        return topic == null
                ? "no such command or topic: " + query
                : topic.stripTrailing();
    }

    private String renderIndex() {
        StringBuilder out = new StringBuilder("""
                ARCHON COMMAND MANUAL
                Type 'help ' for a command page, or 'help ' for a reference guide.

                """);

        Map<String, List> categories = new LinkedHashMap<>();
        for (VerbDefinition definition : catalog.all()) {
            categories.computeIfAbsent(
                    definition.documentation().category(),
                    ignored -> new ArrayList<>()
            ).add(definition);
        }

        for (Map.Entry<String, List> category : categories.entrySet()) {
            out.append(category.getKey()).append(":\n");
            for (VerbDefinition definition : category.getValue()) {
                out.append("  ").append(synopsis(definition))
                        .append(" — ").append(definition.documentation().summary()).append('\n');
                out.append("    ").append(definition.price().describe());
                if (definition.free()) out.append("; free");
                if (definition.terminal()) out.append("; terminal");
                out.append('\n');
            }
            out.append('\n');
        }

        out.append("REFERENCE TOPICS:\n  ");
        out.append(TOPICS.stream()
                .map(topic -> "help " + topic)
                .collect(Collectors.joining(" | ")));
        return out.toString();
    }

    private String renderVerb(VerbDefinition definition) {
        VerbDefinition.Documentation doc = definition.documentation();
        StringBuilder out = new StringBuilder();

        out.append("NAME:\n  ").append(definition.name())
                .append(" — ").append(doc.summary()).append("\n\n");
        out.append("SYNOPSIS:\n  ").append(synopsis(definition));
        for (FlagSpec option : definition.options()) {
            out.append(" [").append(optionSyntax(option)).append(']');
        }
        out.append(" [").append(optionSyntax(FlagSpec.AUDIT)).append("]\n\n");

        out.append("AP COST:\n  ").append(definition.price().describe()).append('\n');
        out.append("  Free: ").append(definition.free() ? "yes" : "no").append('\n');
        out.append("  Terminal: ").append(definition.terminal() ? "yes" : "no").append("\n\n");
        out.append("CATEGORY:\n  ").append(doc.category()).append("\n\n");

        out.append("DESCRIPTION:\n");
        for (String line : doc.description().split("\\R")) {
            out.append("  ").append(line).append('\n');
        }

        out.append("\nPIPELINE:\n");
        out.append("  Accepted kinds: ").append(kinds(definition.input())).append('\n');
        out.append("  Possible output kinds: ").append(kinds(definition.output())).append('\n');
        if (!definition.output().isEmpty()) {
            out.append("  Output is possible, not guaranteed on every invocation.\n");
        }

        out.append("\nOPTIONS:\n");
        for (FlagSpec option : definition.options()) {
            appendOption(out, option);
        }
        appendOption(out, FlagSpec.AUDIT);

        if (!doc.examples().isEmpty()) {
            out.append("\nEXAMPLES:\n");
            for (String example : doc.examples()) {
                out.append("  ").append(example).append('\n');
            }
        }

        return out.toString().stripTrailing();
    }

    private static String synopsis(VerbDefinition definition) {
        String operands = definition.documentation().operands();
        return definition.name() + (operands.isBlank() ? "" : " " + operands);
    }

    private static String optionSyntax(FlagSpec option) {
        String name = option.shortName() == null
                ? "--" + option.name()
                : "-" + option.shortName();
        if (!option.takesValue()) {
            return name;
        }

        String value = "<" + option.valueName() + ">";
        return name + " " + (option.bareDefault() == null ? value : "[" + value + "]");
    }

    private static void appendOption(StringBuilder out, FlagSpec option) {
        out.append("  ");
        if (option.shortName() != null) {
            out.append('-').append(option.shortName()).append(", ");
        }
        out.append("--").append(option.name());
        if (option.takesValue()) {
            out.append(option.bareDefault() == null ? " <" : " [<")
                    .append(option.valueName())
                    .append(option.bareDefault() == null ? ">" : ">]");
        }
        out.append("\n    ").append(option.description());
        if (option.bareDefault() != null) {
            out.append(" Bare option value: ").append(option.bareDefault()).append('.');
        }
        out.append('\n');
    }

    private static String kinds(Set kinds) {
        return kinds.isEmpty()
                ? "none"
                : kinds.stream()
                .sorted()
                .map(kind -> kind.name().toLowerCase(Locale.ROOT))
                .collect(Collectors.joining(", "));
    }

    private String flags() {
        StringBuilder out = new StringBuilder("""
                TOPIC: COMMAND FLAGS
                Options belong to individual commands. An option supported by one command
                is not automatically accepted by another.

                GLOBAL LINE OPTION:
                """);
        appendOption(out, FlagSpec.AUDIT);

        for (VerbDefinition definition : catalog.all()) {
            if (definition.options().isEmpty()) continue;
            out.append('\n').append(definition.name()).append(":\n");
            for (FlagSpec option : definition.options()) {
                appendOption(out, option);
            }
            out.append("  Pricing: ").append(definition.price().describe()).append('\n');
        }

        out.append("""

                PARSING:
                  Short boolean options may be grouped.
                  An option taking a value must be last in a short-option group.
                  Repeated options use the final value.
                  --name=value supplies an inline value.

                CURRENT LIMITATIONS:
                  There is no end-of-options '--' marker.
                  A separated value beginning with '-' is not consumed as an option value.
                  Boolean options are enabled by presence; '--careful=false' still enables it.
                """);
        return out.toString();
    }

    private static String operators() {
        return """
                TOPIC: COMMAND OPERATORS

                ALL LINES, INCLUDING FREE COMMANDS:
                  ;    Continue after any ordinary outcome.
                       Example: step e ; strike o1
                  &&   Continue only after SUCCESS.
                       Successful hits count as SUCCESS, not only kills.
                  ||   Recover after MISS, PARTIAL, or gameplay BLOCKED.
                       Example: strike o1 || guard
                  |    Pass actual material output within one pipeline stage.
                       Example: siphon b1/contents | pour @o1/floor

                BRANCHING:
                  Evaluate stages left to right. Skips preserve the last executed outcome.
                  In 'a && b || c', c runs if a fails or an executed b fails.
                  Ordinary failure does not break a line. Interruption does, without recovery.
                  Malformed commands are rejected before commitment, even in skipped branches.
                  Missing, unsuitable, or currently unreachable targets are gameplay failures.

                PIPELINES:
                  Every non-final command must declare possible output.
                  Its consumer must accept every declared possible output kind.
                  Stop at the first non-success, preserving its outcome.
                  Successful production of no material blocks the next consumer.
                  There is no implicit forwarding of consumed input or fallback to operands.
                  Materials do not cross ;, &&, or ||. Earlier effects are not rolled back.
                  Pour emits nothing and Ignite accepts nothing. Sequence them instead:
                    siphon b1/contents | pour @o1/floor && ignite @o1/floor

                TERMINAL COMMANDS:
                  Must be the final invocation, including on free-only lines.
                  End the round only when actually executed successfully.
                  A skipped terminal or failed upstream producer does not end the round.

                REACTIONS:
                  Check between executed paid stages and after normally completed paid work.
                  Free and skipped stages add no checkpoints. Pipelines add no internal checks.
                  A post-completion reaction does damage but does not retroactively break a line.
                """;
    }

    private static String addressing() {
        return """
                TOPIC: ADDRESSING SYNTAX

                TILES:
                  @x,y                 Absolute tile, for example @3,4.
                  @self                The thrall's current tile.
                  @          The tile occupied by an entity, for example @o1.
                  @x,y/floor           Explicit floor layer.
                  @x,y/ceiling         Explicit ceiling layer.
                  @     Relative tile, for example @e2 or @sw1.

                THRALL INVENTORY:
                  /pack                The pack location, not a selected item.
                  /pack/
         A selected packed item, for example /pack/torch.

                ENTITIES, BODY PARTS, AND EQUIPMENT:
                             The entity itself.
                  /body/head   An explicit body-part target.
                  /body/torso
                  /body/arm.l
                  /body/arm.r
                  /body/legs

                  /head        Equipment location, not the head body part.
                  /hand/right  Right-hand equipment.
                  /hand/left   Left-hand equipment.

                EXAMPLES:
                  inspect o1/body/head
                  strike o1/body/head
                  strike o1/hand/right
                  take o1/hand/right

                EMPTY LOCATIONS:
                  An empty equipment slot, empty prop contents, or pack root is a location,
                  not an item. Commands requiring an item may be blocked by those targets.
                  Resolution does not imply that a command can reach or use a target.
                """;
    }

    private String economy() {
        return """
                TOPIC: ACTION ECONOMY

                ROUND BUDGET:
                  Each round begins with %d AP.
                  Unspent AP is discarded when the round ends.

                LINE TAX:
                  Untaxed paid lines per round: %d.
                  Tax on each subsequent paid line: %d AP.
                  This is fixed, not escalating; commitment tax is never refunded.
                  A submission containing paid work is paid even if that work is later skipped.

                ALLOCATION:
                  A pipeline allocates its final invocation's price, not the sum inside it.
                  A line allocates every stage, including conditional stages.
                  Allocation plus tax must be affordable before commitment.
                  Singles permit adaptation; complex lines commit more work in advance.

                COMPLETION AND RECOVERY:
                  Every attempted ordinary stage pays its normal stage price, including
                  MISS, PARTIAL, BLOCKED, and pipelines whose producer fails.
                  An executed fallback also pays its price. Skipped stages pay nothing.
                  Ordinary failure without successful recovery still has no break penalty.
                  Rejected submissions spend nothing and consume no paid line.

                INTERRUPTIONS:
                  A broken line forfeits its allocation plus %d AP, capped by AP after tax.
                  This replaces ordinary trace charging rather than adding to it.
                  The trace records half the interrupted stage price, rounded down.
                  This applies before a stage begins and during an interrupted pipeline.

                FREE COMMANDS AND AUDITS:
                  Free-only lines use the same language without AP, tax, paid-line counting,
                  movement resets, or runner-managed reactions.
                  Free commands inside paid lines do not remove the commitment tax.
                  Audit shares submission validity, allocation, tax, affordability, and
                  forfeiture calculations. It spends nothing and predicts no future outcomes.

                PASS:
                  A successfully executed terminal requests the end of the round.
                  The application discards remaining AP when advancing the round.
                """.formatted(
                rules.roundAp(),
                rules.untaxedLines(),
                rules.lineTax(),
                rules.breakPenalty()
        );
    }
}



package com.archon.verb;

public final class GuardVerb implements Verb {

    @Override
    public ExitCode execute(VerbContext c) {
        c.thrall.setGuarded(true);
        c.say("Thrall raises its guard.");
        return ExitCode.SUCCESS;
    }
}



package com.archon.verb;

public final class HelpVerb implements Verb {
    private final CommandManual manual;

    public HelpVerb(CommandManual manual) {
        this.manual = java.util.Objects.requireNonNull(manual, "manual");
    }

    @Override
    public ExitCode execute(VerbContext c) {
        c.say(manual.render(c.inv.arg(0)));
        return ExitCode.SUCCESS;
    }
}



package com.archon.verb;

public final class NockVerb implements Verb {

    @Override
    public ExitCode execute(VerbContext c) {
        if (c.thrall.isNocked()) {
            c.say("already nocked");
            return ExitCode.BLOCKED;
        }

        c.thrall.nock();
        c.say("Arrow nocked.");
        return ExitCode.SUCCESS;
    }
}



package com.archon.address;

import com.archon.model.Entity;
import com.archon.model.Vec2;
import com.archon.model.World;

/** Parsed, unresolved reference. Everything addressable is a path. */
public sealed interface Address {
    enum Layer { TILE, FLOOR, CEILING }

    record EntityAddr(String id, String path) implements Address { }
    record InventoryAddr(String path) implements Address { }
    record TileAddr(String spec, Layer layer) implements Address { }
    record Invalid(String reason) implements Address { }

    static Address parse(String source) {
        if (source == null || source.isBlank()) {
            return new Invalid("empty address");
        }
        if (source.endsWith("/") || source.contains("//")) {
            return new Invalid("address contains an empty path segment");
        }

        if (source.startsWith("@")) {
            int slash = source.indexOf('/');
            String spec = slash < 0
                    ? source.substring(1)
                    : source.substring(1, slash);
            String suffix = slash < 0 ? "" : source.substring(slash + 1);

            if (spec.isBlank()) {
                return new Invalid("empty tile specification");
            }

            Layer layer = switch (suffix) {
                case "" -> Layer.TILE;
                case "floor" -> Layer.FLOOR;
                case "ceiling" -> Layer.CEILING;
                default -> null;
            };

            return layer == null
                    ? new Invalid("unknown layer \"" + suffix + "\" (floor, ceiling)")
                    : new TileAddr(spec, layer);
        }

        if (source.startsWith("/")) {
            return new InventoryAddr(source.substring(1));
        }

        int slash = source.indexOf('/');
        String id = slash < 0 ? source : source.substring(0, slash);
        if (id.isBlank()) {
            return new Invalid("empty entity ID");
        }

        return new EntityAddr(id, slash < 0 ? "" : source.substring(slash + 1));
    }
}



package com.archon.exec;

import com.archon.command.Ast;
import com.archon.event.EventBus;
import com.archon.model.Actor;
import com.archon.model.Entity;
import com.archon.model.World;

import java.util.Objects;

public final class Auditor {
    private final World world;
    private final EventBus bus;
    private final RoundState round;
    private final SubmissionChecks submissions;

    public Auditor(World world, EventBus bus, RoundState round, SubmissionChecks submissions) {
        this.world = Objects.requireNonNull(world, "world");
        this.bus = Objects.requireNonNull(bus, "bus");
        this.round = Objects.requireNonNull(round, "round");
        this.submissions = Objects.requireNonNull(submissions, "submissions");
    }

    public SubmissionChecks.Review audit(Ast.Line line) {
        SubmissionChecks.Review review = submissions.review(line);
        SubmissionQuote quote = review.quote();
        StringBuilder out = new StringBuilder("CHAIN AUDIT — nothing spent.\n");
        out.append(String.format("  Verbs: %d — %s%n", line.verbCount(), line.isChain() ? "CHAIN" : "SINGLE"));
        out.append("  SUBMISSION: ").append(
                review.check().valid() ? "ACCEPTED; gameplay outcomes are not predicted" : "REJECT — " + review.check().reason()).append(
                '\n');

        if (quote != null) {
            out.append(String.format("  Allocation: %d AP; tax: %d AP%s%n", quote.allocation(), quote.tax(),
                    quote.free() ? " (free-only)" : ""));
            out.append(
                    String.format("  Required: %d AP; available: %d AP — %s%n", quote.requiredAp(), quote.availableAp(),
                            quote.affordable() ? "AFFORDABLE" : "UNAFFORDABLE"));
        }
        for (int i = 0; i < line.stages().size(); i++) {
            out.append(String.format("    [%d] %s%n", i + 1, line.stages().get(i).render()));
        }

        if (!review.check().valid() || quote.free()) {
            out.append("\n  No paid commitment; no tax or forfeiture.\n");
        } else {
            out.append("""

                      Ordinary attempts and executed recovery stages pay their stage prices.
                      Skipped stages are uncharged. Upstream effects are not rolled back.
                      Reactions are checked between executed paid stages, not at free/skipped
                      stages, and once after normally completed paid work.
                    """);
            for (Entity entity : world.entities()) {
                if (entity instanceof Actor actor && actor.alive() && actor.readied() != null && !actor.isReadiedSpent()) {
                    out.append(String.format("    • %s is READIED (%s, %d dmg)%n", actor.id(),
                            actor.readied().description(), actor.readied().damage()));
                }
            }
            out.append("  Listed readiness is potential exposure, not a trigger prediction.\n");
            out.append(String.format("  IF INTERRUPTED: min(%d allocation + %d penalty, %d AP after tax) = %d AP.%n",
                    quote.allocation(), round.rules().breakPenalty(), quote.availableAp() - quote.tax(),
                    quote.forfeiture()));
            out.append("  This replaces trace charging; commitment tax is additional.\n");
        }
        bus.audit(out.toString().stripTrailing());
        return review;
    }
}



package com.archon.verb;

import com.archon.model.Vec2;
import com.archon.system.spatial.SpatialService;

public final class StepVerb implements Verb {

    @Override
    public Check validateStructural(ValidationContext c) {
        String direction = c.inv.arg(0);
        if (direction == null) {
            return Check.invalid("step needs a direction", "n s e w ne nw se sw");
        }
        if (Vec2.dir(direction) == null) {
            return Check.invalid("unknown direction \"" + direction + "\"", "n s e w ne nw se sw");
        }
        return Check.ok();
    }

    @Override
    public ExitCode execute(VerbContext c) {
        Vec2 destination = c.thrall.pos().plus(Vec2.dir(c.inv.arg(0)));
        if (!SpatialService.passable(c.world, destination)) {
            c.say("blocked at " + destination);
            return ExitCode.BLOCKED;
        }

        c.thrall.moveTo(destination);
        c.world.markThrallMoved();
        c.say("Thrall advances to " + destination + ".");
        return ExitCode.SUCCESS;
    }
}



package com.archon.model;

import java.util.Collections;
import java.util.EnumSet;
import java.util.Objects;
import java.util.Set;

public class Entity {
    public enum Kind { CREATURE, PROP, DOOR }

    private final String id;
    private final String name;
    private final char glyph;
    private final Kind kind;
    private Vec2 pos;
    private int hp;
    private int maxHp;
    private int armor;
    private int evasion;
    private final Set tags = EnumSet.noneOf(Tag.class);
    private boolean identified;

    public Entity(String id, String name, char glyph, Kind kind, Vec2 pos, int hp, int armor, int evasion) {
        if (id == null || id.isBlank()) {
            throw new IllegalArgumentException("id cannot be null or blank");
        }
        if (name == null || name.isBlank()) {
            throw new IllegalArgumentException("name cannot be null or blank");
        }
        if (hp < 0) {
            throw new IllegalArgumentException("initial HP cannot be negative");
        }

        this.id = id;
        this.name = name;
        this.glyph = glyph;
        this.kind = Objects.requireNonNull(kind, "kind cannot be null");
        this.pos = Objects.requireNonNull(pos, "position cannot be null");
        this.hp = hp;
        this.maxHp = hp;
        this.armor = armor;
        this.evasion = evasion;
    }

    public String id() {
        return id;
    }

    public String name() {
        return name;
    }

    public char glyph() {
        return glyph;
    }

    public Kind kind() {
        return kind;
    }

    public Vec2 pos() {
        return pos;
    }

    public int hp() {
        return hp;
    }

    public int maxHp() {
        return maxHp;
    }

    public int armor() {
        return armor;
    }

    public int evasion() {
        return evasion;
    }

    public boolean alive() {
        return hp > 0;
    }

    public Set tags() {
        return Collections.unmodifiableSet(tags);
    }

    public boolean has(Tag tag) {
        return tags.contains(tag);
    }

    public boolean isIdentified() {
        return identified;
    }

    public Entity with(Tag... values) {
        Collections.addAll(tags, values);
        return this;
    }

    public void moveTo(Vec2 destination) {
        pos = Objects.requireNonNull(destination, "destination cannot be null");
    }

    public int takeDamage(int amount) {
        if (amount < 0) {
            throw new IllegalArgumentException("damage cannot be negative");
        }
        hp = amount >= hp ? 0 : hp - amount;
        return hp;
    }

    public int heal(int amount) {
        if (amount < 0) {
            throw new IllegalArgumentException("healing cannot be negative");
        }
        hp = amount >= maxHp - hp ? maxHp : hp + amount;
        return hp;
    }

    public void setMaxHp(int value) {
        if (value < 0) {
            throw new IllegalArgumentException("maximum HP cannot be negative");
        }
        maxHp = value;
        if (hp > maxHp) {
            hp = maxHp;
        }
    }

    public void setArmor(int value) {
        armor = value;
    }

    public void setEvasion(int value) {
        evasion = value;
    }

    public void identify() {
        identified = true;
    }

    public void ignite() {
        tags.add(Tag.BURNING);
    }

    public void extinguish() {
        tags.remove(Tag.BURNING);
    }

    public void applyTag(Tag tag) {
        tags.add(tag);
    }

    public void removeTag(Tag tag) {
        tags.remove(tag);
    }

    @Override
    public String toString() {
        return id;
    }
}



package com.archon.model;

import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;

public final class World {

    private final GameMap map;
    private final Map entities = new LinkedHashMap<>();
    private final Dice dice;
    private Thrall thrall;
    private int roundNumber = 1;
    private boolean thrallMovedThisLine;

    public World(int w, int h, Dice dice) {
        this.map = new GameMap(w, h);
        this.dice = Objects.requireNonNull(dice, "dice");
    }

    public int width() {
        return map.width();
    }

    public int height() {
        return map.height();
    }

    public GameMap map() {
        return map;
    }

    public Dice dice() {
        return dice;
    }

    public int roundNumber() {
        return roundNumber;
    }

    public void advanceRound() {
        roundNumber++;
    }

    public Thrall thrall() {
        return thrall;
    }

    public void installThrall(Thrall thrall) {
        Objects.requireNonNull(thrall, "thrall");

        if (this.thrall != null && this.thrall != thrall) {
            throw new IllegalStateException("A different thrall is already installed");
        }

        String id = Objects.requireNonNull(thrall.id(), "thrall.id");
        if (entities.containsKey(id)) {
            throw new IllegalArgumentException(
                    "Thrall ID collides with a registered entity: " + id
            );
        }

        this.thrall = thrall;
    }

    public Collection entities() {
        return Collections.unmodifiableCollection(entities.values());
    }

    public boolean inBounds(Vec2 p) {
        return map.inBounds(p);
    }

    public GameMap.Tile tile(Vec2 p) {
        return map.tile(p);
    }

    public void add(Entity entity) {
        Objects.requireNonNull(entity, "entity");

        String id = Objects.requireNonNull(entity.id(), "entity.id");
        if ("self".equals(id)) {
            throw new IllegalArgumentException("Entity ID 'self' is reserved");
        }
        if (thrall != null && id.equals(thrall.id())) {
            throw new IllegalArgumentException(
                    "Entity ID collides with the installed thrall: " + id
            );
        }
        if (entities.containsKey(id)) {
            throw new IllegalArgumentException("Duplicate entity ID: " + id);
        }

        entities.put(id, entity);
    }

    public Entity get(String id) {
        if (id == null) {
            return null;
        }
        return "self".equals(id) ? thrall : entities.get(id);
    }

    public Actor actor(String id) {
        Entity entity = get(id);
        return entity instanceof Actor actor ? actor : null;
    }

    public void markThrallMoved() {
        thrallMovedThisLine = true;
    }

    public void resetThrallMovement() {
        thrallMovedThisLine = false;
    }

    public boolean thrallMovedThisLine() {
        return thrallMovedThisLine;
    }
}



package com.archon.system.combat;

import com.archon.model.Actor;
import com.archon.model.Entity;
import com.archon.model.World;
import com.archon.system.spatial.SpatialService;

import java.util.Objects;
import java.util.Optional;

/** Selects and resolves the first triggered, unspent readied reaction. */
public final class ReactionSystem {

    private ReactionSystem() {}

    public static Optional fire(World world) {
        Objects.requireNonNull(world, "world");
        Actor target = world.thrall();
        if (target == null) {
            return Optional.empty();
        }

        for (Entity entity : world.entities()) {
            if (!(entity instanceof Actor actor)) {
                continue;
            }

            Actor.Readied readied = actor.readied();
            if (!actor.alive() || readied == null || actor.isReadiedSpent()) {
                continue;
            }

            boolean triggered = switch (readied.trigger()) {
                case ON_ADJACENCY -> actor.pos().chebyshev(target.pos()) <= 1;
                case ON_MOVEMENT_IN_LOS ->
                        world.thrallMovedThisLine() && SpatialService.lineOfSight(world.map(), actor.pos(),
                                target.pos());
            };
            if (!triggered) {
                continue;
            }

            Reaction reaction = new Reaction(actor.id(), actor.name(), readied.description(), readied.damage());
            actor.spendReadied();
            target.takeDamage(reaction.damage());
            return Optional.of(reaction);
        }

        return Optional.empty();
    }
}



package com.archon.system.environment;

import com.archon.model.Actor;
import com.archon.model.Entity;
import com.archon.model.GameMap;
import com.archon.model.Tag;
import com.archon.model.Vec2;
import com.archon.model.World;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;

/** Periodic burning, actor round resets, and fire propagation. */
public final class SimulationSystem {

    private SimulationSystem() {}

    /**
     * Advances the round, applies burning, resets actors, and spreads fire
     * to adjacent oil tiles using the state before this tick's spread.
     */
    public static List tick(World world) {
        List log = new ArrayList<>();
        world.advanceRound();

        Collection entitySnapshot = new ArrayList<>(world.entities());
        for (Entity entity : entitySnapshot) {
            if (entity.alive() && entity.has(Tag.BURNING)) {
                entity.takeDamage(3);
                log.add(entity.name() + " burns for 3.");

                if (!entity.alive()) {
                    log.add(entity.name() + " is consumed.");
                }
            }

            if (entity instanceof Actor actor) {
                actor.resetRoundState();
            }
        }

        Actor thrall = world.thrall();
        if (thrall.has(Tag.BURNING)) {
            thrall.takeDamage(3);
            log.add("Thrall burns for 3.");
        }
        thrall.resetRoundState();

        GameMap map = world.map();
        List ignite = new ArrayList<>();

        for (int y = 0; y < world.height(); y++) {
            for (int x = 0; x < world.width(); x++) {
                Vec2 position = new Vec2(x, y);
                GameMap.Tile tile = map.tile(position);
                if (!tile.has(Tag.BURNING)) {
                    continue;
                }

                for (Vec2 direction : List.of(Vec2.dir("n"), Vec2.dir("s"), Vec2.dir("e"), Vec2.dir("w"))) {
                    Vec2 adjacent = position.plus(direction);
                    GameMap.Tile adjacentTile = map.tile(adjacent);

                    if (adjacentTile != null && adjacentTile.has(Tag.OIL) && !adjacentTile.has(Tag.BURNING)) {
                        ignite.add(adjacent);
                    }
                }
            }
        }

        for (Vec2 position : ignite) {
            map.addTag(position, Tag.BURNING);
            log.add("Fire spreads to " + position + ".");
        }

        return log;
    }
}



package com.archon.verb;

import com.archon.model.Actor;
import com.archon.model.Entity;
import com.archon.model.Tag;

public final class ScanVerb implements Verb {

    @Override
    public ExitCode execute(VerbContext c) {
        StringBuilder sb = new StringBuilder("VISIBLE:\n");

        for (Entity e : c.world.entities()) {
            if (!e.alive()) {
                continue;
            }

            sb.append(String.format(
                    "  %-5s %-16s %-7s HP %2d/%-2d %s%s%s%n",
                    e.id(),
                    e.name(),
                    e.pos().toString(),
                    e.hp(),
                    e.maxHp(),
                    e.tags().contains(Tag.BURNING) ? "[BURNING] " : "",
                    e instanceof Actor actor && actor.readied() != null
                            ? "[READIED: " + actor.readied().description() + "] "
                            : "",
                    e.pos().chebyshev(c.thrall.pos()) <= 1
                            ? "adjacent"
                            : "range " + e.pos().chebyshev(c.thrall.pos())
            ));
        }

        c.say(sb.toString().stripTrailing());
        return ExitCode.SUCCESS;
    }
}



package com.archon.verb;

import com.archon.address.Resolved;

public final class InspectVerb implements Verb {

    @Override
    public Check validateStructural(ValidationContext c) {
        return VerbSyntax.address(c, 0);
    }

    @Override
    public ExitCode execute(VerbContext c) {
        Resolved resolved = VerbHelpers.resolve(c, c.inv.arg(0));
        Check check = VerbTargets.resolution(resolved);
        if (!check.valid()) return VerbTargets.reject(c, check);

        c.say(TargetDescriptions.inspect(c.world, (Resolved.Target) resolved));
        return ExitCode.SUCCESS;
    }
}



package com.archon.verb;

import com.archon.address.Resolved;
import com.archon.verb.*;

import java.util.Optional;

public final class LsVerb implements Verb {

    @Override
    public Check validateStructural(ValidationContext c) {
        return VerbSyntax.optionalAddress(c, 0);
    }

    @Override
    public ExitCode execute(VerbContext c) {
        String address = c.inv.arg(0) == null ? "/pack" : c.inv.arg(0);
        Resolved resolved = VerbHelpers.resolve(c, address);
        Check check = VerbTargets.resolution(resolved);
        if (!check.valid()) return VerbTargets.reject(c, check);

        Optional listing = TargetDescriptions.list(c.world, (Resolved.Target) resolved);
        if (listing.isEmpty()) {
            return VerbTargets.reject(c, Check.blocked("nothing to list at " + address, null));
        }
        c.say(listing.get());
        return ExitCode.SUCCESS;
    }
}



package com.archon.verb;

import com.archon.model.Tag;
import com.archon.model.Vec2;
import com.archon.system.environment.Substances;

public final class PourVerb implements Verb {

    @Override
    public Check validateStructural(ValidationContext c) {
        return VerbSyntax.delivery(c);
    }

    @Override
    public ExitCode execute(VerbContext c) {
        DeliveryTarget destination = DeliveryTarget.select(c, DeliveryTarget.Mode.POUR);
        if (destination instanceof DeliveryTarget.Rejected rejected) {
            return VerbTargets.reject(c, rejected.check());
        }
        Vec2 at = ((DeliveryTarget.Selected) destination).pos();

        Tag substance;
        if (c.materialIn instanceof Material.OfSubstance material) {
            substance = material.substance();
            if (substance != null) {
                Substances.spill(c.world, at, substance);
            }
        } else {
            ItemInput input = ItemInput.select(c, 0);
            if (input instanceof ItemInput.Rejected rejected) {
                return VerbTargets.reject(c, rejected.check());
            }
            substance = Substances.pour(c.world, at, ((ItemInput.Selected) input).target().item());
        }

        if (substance == null) {
            return VerbTargets.reject(c, Check.blocked("nothing pourable", null));
        }
        VerbHelpers.describeSpill(c, at, substance);
        return ExitCode.SUCCESS;
    }
}



package com.archon.verb;

import com.archon.address.Address;
import com.archon.address.Resolved;
import com.archon.system.environment.Substances;

public final class SiphonVerb implements Verb {

    @Override
    public Check validateStructural(ValidationContext c) {
        return VerbSyntax.address(c, 0);
    }

    @Override
    public ExitCode execute(VerbContext c) {
        Resolved resolved = VerbHelpers.resolve(c, c.inv.arg(0));
        Check resolution = VerbTargets.resolution(resolved);
        if (!resolution.valid()) {
            return VerbTargets.reject(c, resolution);
        }
        if (resolved instanceof Resolved.OnTile tile && tile.layer() == Address.Layer.CEILING) {
            return VerbTargets.reject(c, Check.blocked("cannot siphon from the ceiling", null));
        }

        Resolved.Target target = (Resolved.Target) resolved;
        Check reach = VerbTargets.reachable(c, target);
        if (!reach.valid()) {
            return VerbTargets.reject(c, reach);
        }

        Substances.Extraction extraction = Substances.extract(c.world, target);
        if (!(extraction instanceof Substances.Portion portion)) {
            Check failure = extraction == Substances.Unavailable.STALE_SOURCE
                    ? Check.blocked("item no longer at its source", null)
                    : Check.blocked("nothing to siphon", "try: inspect " + c.inv.arg(0));
            return VerbTargets.reject(c, failure);
        }

        c.materialOut = new Material.OfSubstance(portion.substance());
        c.say("Thrall draws " + portion.substance().name().toLowerCase() + ".");
        return ExitCode.SUCCESS;
    }
}



package com.archon.verb;

import com.archon.model.Tag;
import com.archon.model.Vec2;
import com.archon.system.environment.Substances;
import com.archon.system.item.ItemMoves;

public final class ThrowVerb implements Verb {

    @Override
    public Check validateStructural(ValidationContext c) {
        return VerbSyntax.delivery(c);
    }

    @Override
    public ExitCode execute(VerbContext c) {
        DeliveryTarget destination = DeliveryTarget.select(c, DeliveryTarget.Mode.THROW);
        if (destination instanceof DeliveryTarget.Rejected rejected) {
            return VerbTargets.reject(c, rejected.check());
        }

        ItemInput input = ItemInput.select(c, 0);
        if (input instanceof ItemInput.Rejected rejected) {
            return VerbTargets.reject(c, rejected.check());
        }
        var selected = ((ItemInput.Selected) input).target();
        var result = ItemMoves.remove(c.world.map(), selected.item(), selected.location());
        if (result != ItemMoves.Result.SUCCESS) {
            return VerbTargets.reject(c, Check.blocked(result.reason(), null));
        }

        Vec2 at = ((DeliveryTarget.Selected) destination).pos();
        c.say(selected.item().name() + " arcs toward " + at + " and shatters.");
        Tag substance = Substances.pour(c.world, at, selected.item());
        if (substance != null) {
            VerbHelpers.describeSpill(c, at, substance);
        }
        return ExitCode.SUCCESS;
    }
}



package com.archon.system.combat;

import com.archon.model.Actor;
import com.archon.model.BodyPart;
import com.archon.model.Dice;
import com.archon.model.EquipmentSlot;
import com.archon.model.Entity;
import com.archon.model.Item;
import com.archon.model.ItemLocation;
import com.archon.model.Thrall;
import com.archon.model.World;
import com.archon.system.item.ItemMoves;

import java.util.Objects;

/**
 * Domain service encapsulating combat calculations and state mutations
 * for melee strikes, ranged attacks, and disarm maneuvers.
 */
public final class CombatEngine {
    private CombatEngine() {}

    public record MeleeHitResult(boolean hit, int hitChance, int damage, BodyPart part, Item weapon, boolean killed,
                                 boolean weaponDegraded) {}

    public record DisarmResult(boolean success, Item weapon) {}

    public record RangedHitResult(boolean hit, int hitChance, int damage, BodyPart part, boolean killed) {}

    public static MeleeHitResult resolveMelee(Dice dice, World world, Thrall attacker, Entity target, BodyPart part,
                                              String power, boolean force) {
        Objects.requireNonNull(world, "world");
        int hitChance = 70 + part.hitMod - target.evasion() + ("light".equals(power) ? 20 : "heavy".equals(
                power) ? -20 : 0);
        if (target instanceof Actor actor && actor.isGuarded() && !force) {
            hitChance -= 25;
        }

        hitChance = clampHitChance(hitChance);
        Item weapon = attacker.mainHand();
        if (!dice.chance(hitChance)) {
            return new MeleeHitResult(false, hitChance, 0, part, weapon, false, false);
        }

        int baseDamage = (weapon == null ? 3 : weapon.damage()) + attacker.strength();
        double multiplier = part.damageMult * ("light".equals(power) ? 0.6 : "heavy".equals(power) ? 1.6 : 1.0);
        int damage = Math.max(1, (int) Math.round(baseDamage * multiplier) - target.armor());
        target.takeDamage(damage);

        boolean weaponDegraded = force && weapon != null;
        if (weaponDegraded) {
            weapon.wear(1);
        }

        boolean killed = !target.alive();
        if (killed) {
            dropMainHand(world, target);
        }
        return new MeleeHitResult(true, hitChance, damage, part, weapon, killed, weaponDegraded);
    }

    public static DisarmResult attemptDisarm(Dice dice, World world, Actor owner, EquipmentSlot slot) {
        Objects.requireNonNull(world, "world");
        Objects.requireNonNull(owner, "owner");
        if (slot != EquipmentSlot.HAND_LEFT && slot != EquipmentSlot.HAND_RIGHT) {
            throw new IllegalArgumentException("disarm requires a hand slot");
        }

        Item weapon = owner.inventory().equipped(slot);
        if (weapon == null) {
            return new DisarmResult(false, null);
        }
        if (!dice.chance(45)) {
            return new DisarmResult(false, weapon);
        }

        ItemMoves.drop(world.map(), weapon, new ItemLocation.Equipment(owner, slot)).requireSuccess();
        return new DisarmResult(true, weapon);
    }

    public static RangedHitResult resolveRanged(Dice dice, World world, Thrall attacker, Entity target, BodyPart part) {
        Objects.requireNonNull(world, "world");
        int distance = target.pos().chebyshev(attacker.pos());
        int rangeModifier = distance <= 1 ? -20 : distance <= 4 ? 0 : distance <= 8 ? -10 : -25;
        int hitChance = clampHitChance(70 + part.hitMod + rangeModifier - target.evasion());

        if (!dice.chance(hitChance)) {
            return new RangedHitResult(false, hitChance, 0, part, false);
        }

        int damage = Math.max(1, dice.between(5, 10) - target.armor());
        target.takeDamage(damage);

        boolean killed = !target.alive();
        if (killed) {
            dropMainHand(world, target);
        }
        return new RangedHitResult(true, hitChance, damage, part, killed);
    }

    private static int clampHitChance(int hitChance) {
        return Math.max(5, Math.min(95, hitChance));
    }

    private static void dropMainHand(World world, Entity target) {
        if (!(target instanceof Actor actor)) {
            return;
        }

        Item item = actor.mainHand();
        if (item != null) {
            EquipmentSlot slot = actor.inventory().equipped(
                    EquipmentSlot.HAND_RIGHT) == item ? EquipmentSlot.HAND_RIGHT : EquipmentSlot.HAND_LEFT;
            ItemMoves.drop(world.map(), item, new ItemLocation.Equipment(actor, slot)).requireSuccess();
        }
    }
}



package com.archon.verb;

import com.archon.address.Resolved;
import com.archon.model.BodyPart;
import com.archon.model.Entity;
import com.archon.system.combat.CombatEngine;
import com.archon.system.spatial.SpatialService;

public final class ShootVerb implements Verb {

    @Override
    public Check validateStructural(ValidationContext c) {
        return VerbSyntax.aimedAddress(c, false);
    }

    private Check check(ValidationContext c, Resolved resolved) {
        Check resolution = VerbTargets.resolution(resolved);
        if (!resolution.valid()) return resolution;
        if (!(resolved instanceof Resolved.OnEntity || resolved instanceof Resolved.OnBody)) {
            return Check.blocked("shoot needs an entity or body-part target", null);
        }
        if (!c.thrall.isNocked()) {
            return Check.blocked("nothing nocked", "try: nock ; shoot ");
        }

        Entity target = VerbHelpers.targetEntity(resolved).orElseThrow();
        return SpatialService.lineOfSight(c.world, c.thrall.pos(), target.pos()) ? Check.ok() : Check.blocked(
                "no line of fire", null);
    }

    @Override
    public ExitCode execute(VerbContext c) {
        Resolved resolved = VerbHelpers.resolve(c, c.inv.arg(0));
        Check check = check(c, resolved);
        if (!check.valid()) return VerbTargets.reject(c, check);

        Entity target = VerbHelpers.targetEntity(resolved).orElseThrow();
        BodyPart part = VerbHelpers.aimPart(c.inv, resolved).orElseThrow();
        c.thrall.fireNocked();

        CombatEngine.RangedHitResult result = CombatEngine.resolveRanged(c.world.dice(), c.world, c.thrall, target,
                part);
        if (!result.hit()) {
            c.say("Arrow flies wide of " + target.name() + ".");
            return ExitCode.MISS;
        }

        c.say("Arrow strikes " + target.name() + "'s " + part.path + ". " + result.damage() + " dmg.");
        if (result.killed()) {
            c.say(target.name() + " falls.");
        }
        return ExitCode.SUCCESS;
    }
}



package com.archon.verb;

import com.archon.address.Resolved;
import com.archon.model.*;
import com.archon.system.combat.CombatEngine;

import java.util.Locale;
import java.util.Set;

public final class StrikeVerb implements Verb {

    @Override
    public Check validateStructural(ValidationContext c) {
        String power = c.inv.flag("power");
        if (power != null && !Set.of("light", "normal", "heavy")
                .contains(power.toLowerCase(Locale.ROOT))) {
            return Check.invalid("unknown power \"" + power + "\"", "light, normal, heavy");
        }
        return VerbSyntax.aimedAddress(c, true);
    }

    private Resolved resolveTarget(ValidationContext c) {
        String address = c.inv.arg(0);
        if (address == null) address = VerbHelpers.soleAdjacentHostile(c);
        return address == null
                ? new Resolved.Failure(
                Resolved.Problem.UNKNOWN_ENTITY,
                "no single adjacent target; name one explicitly"
        )
                : VerbHelpers.resolve(c, address);
    }

    private boolean isHandTarget(Resolved resolved) {
        return resolved instanceof Resolved.ItemTarget target
                && target.location() instanceof ItemLocation.Equipment equipment
                && (equipment.slot() == EquipmentSlot.HAND_LEFT
                || equipment.slot() == EquipmentSlot.HAND_RIGHT);
    }

    private Check check(ValidationContext c, Resolved resolved) {
        Check resolution = VerbTargets.resolution(resolved);
        if (!resolution.valid()) return resolution;
        if (!(resolved instanceof Resolved.OnEntity
                || resolved instanceof Resolved.OnBody || isHandTarget(resolved))) {
            return Check.blocked("strike needs an entity, body part, or hand slot", null);
        }
        if (isHandTarget(resolved) && resolved instanceof Resolved.OnLocation) {
            return Check.blocked("nothing in that hand to disarm", null);
        }
        return VerbTargets.reachable(c, (Resolved.Target) resolved);
    }

    @Override
    public ExitCode execute(VerbContext c) {
        Resolved resolved = resolveTarget(c);
        Check check = check(c, resolved);
        if (!check.valid()) return VerbTargets.reject(c, check);

        if (resolved instanceof Resolved.OnItem item
                && item.location() instanceof ItemLocation.Equipment equipment) {
            Actor owner = equipment.owner();
            CombatEngine.DisarmResult result = CombatEngine.attemptDisarm(
                    c.world.dice(), c.world, owner, equipment.slot()
            );
            if (result.success()) {
                c.say("The " + result.weapon().name() + " is knocked from " + owner.name() + "'s grip.");
                return ExitCode.SUCCESS;
            }
            c.say("The blow glances off " + owner.name() + "'s weapon.");
            return ExitCode.MISS;
        }

        Entity target = VerbHelpers.targetEntity(resolved).orElseThrow();
        BodyPart part = VerbHelpers.aimPart(c.inv, resolved).orElseThrow();
        String power = c.inv.flag("power") == null
                ? "normal" : c.inv.flag("power").toLowerCase(Locale.ROOT);
        CombatEngine.MeleeHitResult result = CombatEngine.resolveMelee(
                c.world.dice(), c.world, c.thrall, target, part, power, c.inv.hasFlag("force")
        );
        if (!result.hit()) {
            c.say("Strike at " + target.name() + "'s " + part.path + " — MISS.");
            return ExitCode.MISS;
        }
        c.say(String.format(
                "%s strikes %s's %s. %d dmg.",
                result.weapon() == null ? "Bare limb" : result.weapon().name(),
                target.name(), part.path, result.damage()
        ));
        if (result.killed()) {
            c.say(target.name() + " falls.");
        }
        return ExitCode.SUCCESS;
    }
}



package com.archon.verb;

import com.archon.address.Address;
import com.archon.address.Resolved;
import com.archon.command.Ast;
import com.archon.model.BodyPart;
import com.archon.model.Entity;
import com.archon.model.Tag;
import com.archon.model.Vec2;
import com.archon.system.spatial.SpatialService;

import java.util.List;
import java.util.Optional;

public final class VerbHelpers {
    private VerbHelpers() {}

    public static Resolved resolve(ValidationContext c, String raw) {
        return Resolved.resolve(Address.parse(raw), c.world);
    }

    public static Optional targetEntity(Resolved resolved) {
        if (resolved instanceof Resolved.OnEntity target) {
            return Optional.of(target.entity());
        }
        if (resolved instanceof Resolved.OnBody target) {
            return Optional.of(target.actor());
        }
        return Optional.empty();
    }

    public static Optional aimPart(Ast.Invocation inv, Resolved resolved) {
        String aim = inv.flag("aim");
        if (aim != null) {
            return Optional.ofNullable(BodyPart.parse(aim));
        }
        return Optional.of(resolved instanceof Resolved.OnBody body ? body.part() : BodyPart.TORSO);
    }

    public static String soleAdjacentHostile(ValidationContext c) {
        List hostiles = SpatialService.hostilesAdjacentTo(c.world, c.thrall.pos());
        return hostiles.size() == 1 ? hostiles.getFirst().id() : null;
    }

    public static void describeSpill(VerbContext c, Vec2 at, Tag substance) {
        c.say(substance.name().toLowerCase() + " spreads across " + at + ".");
    }
}



package com.archon.address;

import com.archon.model.*;

import java.util.Objects;

public sealed interface Resolved {
    enum Problem {
        BAD_SYNTAX, UNKNOWN_ENTITY, DEAD_ENTITY, UNSUPPORTED_PATH, ITEM_NOT_FOUND, INVALID_TILE, OUT_OF_BOUNDS
    }

    sealed interface Target extends Resolved {
        Vec2 pos();
    }

    sealed interface ItemTarget extends Target {
        ItemLocation location();

        default Vec2 pos() {return location().pos();}
    }

    record OnEntity(Entity entity) implements Target {
        public OnEntity {Objects.requireNonNull(entity, "entity");}
        public Vec2 pos() {return entity.pos();}
    }

    record OnBody(Actor actor, BodyPart part) implements Target {
        public OnBody {
            Objects.requireNonNull(actor, "actor");
            Objects.requireNonNull(part, "part");
        }
        public Vec2 pos() {return actor.pos();}
    }

    record OnItem(Item item, ItemLocation location) implements ItemTarget {
        public OnItem {
            Objects.requireNonNull(item, "item");
            Objects.requireNonNull(location, "location");
        }
    }

    record OnLocation(ItemLocation location) implements ItemTarget {
        public OnLocation {Objects.requireNonNull(location, "location");}
    }

    record OnTile(Vec2 pos, Address.Layer layer) implements Target {
        public OnTile {
            Objects.requireNonNull(pos, "pos");
            Objects.requireNonNull(layer, "layer");
        }
    }

    record Failure(Problem problem, String reason) implements Resolved {
        public Failure {
            Objects.requireNonNull(problem, "problem");
            Objects.requireNonNull(reason, "reason");
        }
    }

    static Resolved resolve(Address address, World world) {
        Objects.requireNonNull(world.thrall(), "install a thrall before resolving addresses");
        return switch (Objects.requireNonNull(address, "address")) {
            case Address.Invalid invalid -> new Failure(Problem.BAD_SYNTAX, invalid.reason());
            case Address.EntityAddr entity -> PathResolver.entity(entity, world);
            case Address.InventoryAddr inventory -> PathResolver.inventory(world.thrall(), inventory.path());
            case Address.TileAddr tile -> TileResolver.resolve(tile, world);
        };
    }
}



package com.archon.app;

import com.archon.model.Actor;
import com.archon.model.CreatureStats;
import com.archon.model.Dice;
import com.archon.model.Door;
import com.archon.model.EquipmentSlot;
import com.archon.model.Item;
import com.archon.model.Prop;
import com.archon.model.Tag;
import com.archon.model.Thrall;
import com.archon.model.Vec2;
import com.archon.model.World;

import java.util.Set;

/** The single hand-built test chamber. Layout is fixed so acceptance tests stay stable. */
public final class Scenario {

    public static World testRoom(Dice dice) {
        World world = new World(12, 8, dice);

        for (int x = 0; x < world.width(); x++) {
            world.map().setWall(new Vec2(x, 0), true);
            world.map().setWall(new Vec2(x, world.height() - 1), true);
        }
        for (int y = 0; y < world.height(); y++) {
            world.map().setWall(new Vec2(0, y), true);
            world.map().setWall(new Vec2(world.width() - 1, y), true);
        }
        world.map().setWall(new Vec2(3, 3), true);

        Thrall t = new Thrall(new Vec2(3, 4), 40);
        t.inventory().placeInSlotForSetup(
                EquipmentSlot.HAND_RIGHT,
                Item.weapon("rusted_cleaver", "rusted cleaver", 6, 10, Tag.METAL));
        t.inventory().placeInSlotForSetup(
                EquipmentSlot.HAND_LEFT,
                new Item("torch", "torch", Set.of(Tag.WOOD, Tag.LIT), null, 20, 1));
        t.inventory().addToPack(Item.flask("flask_oil", "oil flask", Tag.OIL));
        t.inventory().addToPack(Item.flask("flask_water", "water flask", Tag.WATER));
        world.installThrall(t);

        Actor orc = new Actor("o1", "Orc Guard", 'O', new Vec2(3, 5), new CreatureStats(24, 3, 5));
        orc.inventory().placeInSlotForSetup(
                EquipmentSlot.HAND_RIGHT,
                Item.weapon("iron_sword", "iron sword", 7, 12, Tag.METAL));
        orc.with(Tag.ORGANIC, Tag.FLESH, Tag.FLAMMABLE);
        world.add(orc);

        Actor archer =
                new Actor("g1", "Goblin Archer", 'G', new Vec2(8, 4), new CreatureStats(12, 0, 10));
        archer.with(Tag.ORGANIC, Tag.FLESH, Tag.FLAMMABLE);
        archer.ready(Actor.Trigger.ON_MOVEMENT_IN_LOS, "fires on movement in line of sight", 6);
        world.add(archer);

        Prop barrel = new Prop("b1", "Oil Barrel", 'B', new Vec2(2, 5), 8);
        barrel.with(Tag.WOOD, Tag.CONTAINER, Tag.FLAMMABLE, Tag.BREAKABLE);
        barrel.setContents(
                new Item(
                        "oil",
                        "oil",
                        Set.of(Tag.LIQUID, Tag.OIL, Tag.FLAMMABLE),
                        Tag.OIL,
                        1,
                        0));
        world.add(barrel);

        Prop brazier = new Prop("br1", "Brazier", 'i', new Vec2(4, 5), 10);
        brazier.with(Tag.METAL, Tag.LIT);
        world.add(brazier);

        Door door = new Door("d1", "Oak Door", '+', new Vec2(2, 3), 30, 10);
        door.setArmor(2);
        door.with(Tag.WOOD, Tag.BREAKABLE, Tag.SOLID, Tag.FLAMMABLE);
        world.add(door);

        return world;
    }
}



package com.archon.model;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

/** Equipment and carried items. Every item instance occupies at most one location. */
public final class Inventory {
    public static final int PACK_MAX = 8;

    private final EnumMap equipment = new EnumMap<>(EquipmentSlot.class);
    private final ArrayList
 pack = new ArrayList<>();

    public Inventory() {
        for (EquipmentSlot slot : EquipmentSlot.values()) {
            equipment.put(slot, null);
        }
    }

    public boolean isPackFull() {
        return pack.size() >= PACK_MAX;
    }

    public boolean isPackEmpty() {
        return pack.isEmpty();
    }

    public Map equipment() {
        return Collections.unmodifiableMap(equipment);
    }

    public List
 pack() {
        return Collections.unmodifiableList(pack);
    }

    public Item equipped(EquipmentSlot slot) {
        return equipment.get(slot);
    }

    public Optional
 find(String query) {
        if (query == null || query.isBlank()) {
            return Optional.empty();
        }

        return pack.stream()
                .filter(item -> item.id().equalsIgnoreCase(query) || item.name().equalsIgnoreCase(query))
                .findFirst();
    }

    /** Scenario/setup-only placement. Runtime transfers use named operations below. */
    public void placeInSlotForSetup(EquipmentSlot slot, Item item) {
        Objects.requireNonNull(slot, "equipment slot cannot be null");
        if (item == null) {
            throw new IllegalArgumentException("equipment item cannot be null");
        }
        if (contains(item)) {
            throw new IllegalArgumentException("item is already in this inventory");
        }
        if (equipment.get(slot) != null) {
            throw new IllegalStateException("equipment slot already occupied: " + slot.path);
        }

        equipment.put(slot, item);
    }

    public boolean addToPack(Item item) {
        if (item == null || isPackFull() || contains(item)) {
            return false;
        }

        pack.add(item);
        return true;
    }

    public boolean equipFromPack(Item item, EquipmentSlot slot) {
        Objects.requireNonNull(slot, "equipment slot cannot be null");

        if (item == null || !removePackedIdentity(item)) {
            return false;
        }

        Item displaced = equipment.put(slot, item);
        if (displaced != null) {
            pack.add(displaced);
        }

        return true;
    }

    public boolean unequipToPack(EquipmentSlot slot) {
        Objects.requireNonNull(slot, "equipment slot cannot be null");

        Item item = equipment.get(slot);
        if (item == null) {
            return true;
        }
        if (isPackFull()) {
            return false;
        }

        equipment.put(slot, null);
        pack.add(item);
        return true;
    }

    public Item removeEquipped(EquipmentSlot slot) {
        Objects.requireNonNull(slot, "equipment slot cannot be null");
        return equipment.put(slot, null);
    }

    /** Removes an owned item without moving it elsewhere. */
    public boolean remove(Item item) {
        if (item == null) {
            return false;
        }
        if (removePackedIdentity(item)) {
            return true;
        }

        for (EquipmentSlot slot : EquipmentSlot.values()) {
            if (equipment.get(slot) == item) {
                equipment.put(slot, null);
                return true;
            }
        }

        return false;
    }

    private boolean contains(Item item) {
        if (pack.stream().anyMatch(candidate -> candidate == item)) {
            return true;
        }

        return equipment.values().stream().anyMatch(candidate -> candidate == item);
    }

    private boolean removePackedIdentity(Item item) {
        for (int index = 0; index < pack.size(); index++) {
            if (pack.get(index) == item) {
                pack.remove(index);
                return true;
            }
        }

        return false;
    }
}



